VALUES ('doc-09-mitre-attack-p0-7445', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-18T16:52:10.043Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "For the Outlook methods, blocking macros may be ineffective as the Visual Basic engine used for these features is separate from the macro scripting engine.(Citation: SensePost Outlook Forms) Microsoft has released patches to try to address each issue. Ensure KB3191938 which blocks Outlook Visual Basic and displays a malicious code warning, KB4011091 which disables custom forms by default, and KB4011162 which removes the legacy Home Page feature, are applied to systems.(Citation: SensePost Outlook Home Page)", "external_references": [{"description": "Stalmans, E. (2017, April 28). Outlook Forms and Shells. Retrieved February 4, 2019.", "source_name": "SensePost Outlook Forms", "url": "https://sensepost.com/blog/2017/outlook-forms-and-shells/"}, {"description": "Stalmans, E. (2017, October 11). Outlook Home Page – Another Ruler Vector. Retrieved February 4, 2019.", "source_name": "SensePost Outlook Home Page", "url": "https://sensepost.com/blog/2017/outlook-home-page-another-ruler-vector/"}], "id": "relationship--7da3b985-e6ab-4e29-aa53-30a621bd48d3", "modified": "2026-04-29T14:23:06.097Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--2c4d4e92-0ccf-4a97-b54c-86d662988a53", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7445', 0, 149, '09-mitre-attack', 'retrieved', 'B0576872051904383F1CD44B70166CF9243320BF5C2C121C42831C56212154EC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
