VALUES ('doc-09-mitre-attack-p0-7447', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-27T19:51:21.977Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Apply patch KB2962486 which prevents credentials from being stored in GPPs.(Citation: ADSecurity Finding Passwords in SYSVOL)(Citation: MS14-025)", "external_references": [{"description": "Sean Metcalf. (2015, December 28). Finding Passwords in SYSVOL & Exploiting Group Policy Preferences. Retrieved February 17, 2020.", "source_name": "ADSecurity Finding Passwords in SYSVOL", "url": "https://adsecurity.org/?p=2288"}, {"description": "Microsoft. (2014, May 13). MS14-025: Vulnerability in Group Policy Preferences could allow elevation of privilege. Retrieved February 17, 2020.", "source_name": "MS14-025", "url": "https://support.microsoft.com/en-us/help/2962486/ms14-025-vulnerability-in-group-policy-preferences-could-allow-elevati"}], "id": "relationship--92a0aa90-109d-41d7-a08a-6326480d02e6", "modified": "2026-04-29T14:23:06.125Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--8d7bd4f5-3a89-4453-9c82-2c8894d5655e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7447', 0, 98, '09-mitre-attack', 'retrieved', 'D2B776B1074AE4960273E4FC37327FEB2F3711E47C6AB809269D66A22B1CCAF3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
