VALUES ('doc-09-mitre-attack-p0-7461', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T14:56:24.423Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Microsoft released an optional patch update - KB3045645 - that will remove the \"auto-elevate\" flag within the sdbinst.exe. This will prevent use of application shimming to bypass UAC.", "id": "relationship--e9fd0f73-917d-4d53-9843-a1314720942f", "modified": "2026-04-29T14:23:06.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--42fe883a-21ea-4cfb-b94a-78b6476dcc83", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7461', 0, 57, '09-mitre-attack', 'retrieved', 'ED8D611DE91AD12C003200DA310841569B230E8220E703EBAC008FC7ACE03F4F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
