VALUES ('doc-09-mitre-attack-p0-7463', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-28T16:16:48.196Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Perform regular software updates to mitigate exploitation risk.", "id": "relationship--fc2f3e79-2740-4113-9875-4193b532d73e", "modified": "2026-08-04T20:30:57.046Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e5d930e9-775a-40ad-9bdb-b941d8dfe86b", "spec_version": "2.1", "target_ref": "attack-pattern--b6301b64-ef57-4cce-bb0b-77026f14a8db", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7463', 0, 37, '09-mitre-attack', 'retrieved', '74B627E4A509630A16AAB104FB99B3526006F0F755DC2EF85D1F916BD5C78884', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
