VALUES ('doc-09-mitre-attack-p0-7465', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T18:38:56.145Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure safe DLL search mode is enabled HKEY_LOCAL_MACHINE\\\\System\\\\CurrentControlSet\\\\Control\\\\Session Manager\\\\SafeDllSearchMode to mitigate risk that lsass.exe loads a malicious code library. (Citation: Microsoft DLL Security)", "external_references": [{"description": "Microsoft. (n.d.). Dynamic-Link Library Security. Retrieved November 27, 2017.", "source_name": "Microsoft DLL Security", "url": "https://msdn.microsoft.com/library/windows/desktop/ff919712.aspx"}], "id": "relationship--71bcc1dc-2392-448a-8133-f126fed08023", "modified": "2026-04-29T14:23:06.081Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e8242a33-481c-4891-af63-4cf3e4cf6aff", "spec_version": "2.1", "target_ref": "attack-pattern--f0589bc3-a6ae-425a-a3d5-5659bfee07f4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7465', 0, 69, '09-mitre-attack', 'retrieved', '01A76A221D8CBD7A791A9A86BEE59BF6124402A0605771CDF0B5D49EA31F54CF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
