VALUES ('doc-09-mitre-attack-p0-7466', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-13T18:11:08.483Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disallow loading of remote DLLs. This is included by default in Windows Server 2012+ and is available by patch for XP+ and Server 2003+.(Citation: Microsoft More information about DLL)\n\nEnable Safe DLL Search Mode to move the user''s current folder later in the search order. This is included by default in modern versions of Windows; the associated Windows Registry key is located at HKLM\\SYSTEM\\CurrentControlSet\\Control\\Session Manager\\SafeDLLSearchMode .(Citation: Microsoft Dynamic Link Library Search Order)", "external_references": [{"description": "Microsoft. (2010, August 12). More information about the DLL Preloading remote attack vector. Retrieved December 5, 2014.", "source_name": "Microsoft More information about DLL", "url": "https://msrc-blog.microsoft.com/2010/08/23/more-information-about-the-dll-preloading-remote-attack-vector/"}, {"description": "Microsoft. (2018, May 31). Dynamic-Link Library Search Order. Retrieved November 30, 2014.", "source_name": "Microsoft Dynamic Link Library Search Order", "url": "https://docs.microsoft.com/en-us/windows/win32/dlls/dynamic-link-library-search-order?redirectedfrom=MSDN"}], "id": "relationship--92764952-45ad-4cfc-a426-c6baefc9974c", "modified": "2026-04-29T14:23:06.125Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--e8242a33-481c-4891-af63-4cf3e4cf6aff", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7466', 0, 149, '09-mitre-attack', 'retrieved', '0396A51EE98758AF5935787476AEBB9E043F1393308BAEF744BF8A92BEEFD883', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
