VALUES ('doc-09-mitre-attack-p0-7467', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T18:15:06.948Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "This feature can be disabled entirely with the following terminal command: defaults write -g ApplePersistence -bool no .", "id": "relationship--025b9140-a0aa-4802-b60c-a4fcb886f90c", "modified": "2026-04-29T14:23:05.906Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--e5cc9e7a-e61a-46a1-b869-55fb6eab058e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7467', 0, 47, '09-mitre-attack', 'retrieved', 'C04459F78F505B1506C30B09B087B835ABC6A464849100E3DBDC49CF88A53962', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
