VALUES ('doc-09-mitre-attack-p0-7469', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-20T22:23:19.511Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Do not allow users to add new application integrations into a SaaS environment. In Entra ID environments, consider enforcing the “Do not allow user consent” option.(Citation: Microsoft Entra Configure OAuth Consent)", "external_references": [{"description": "Microsoft Entra. (2024, September 16). Configure how users consent to applications. Retrieved March 20, 2025.", "source_name": "Microsoft Entra Configure OAuth Consent", "url": "https://learn.microsoft.com/en-us/entra/identity/enterprise-apps/configure-user-consent?pivots=portal"}], "id": "relationship--03a0056f-4d2f-4ef2-b33f-907e6ef30aa9", "modified": "2026-04-29T14:23:05.908Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--c31aebd6-c9b5-420f-ba2a-5853bbf897fa", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7469', 0, 85, '09-mitre-attack', 'retrieved', '3AD81A9971994CB4DD95C0E3142A30629FD7783DFA1A0665B126911F9AC902FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
