VALUES ('doc-09-mitre-attack-p0-7471', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T14:29:52.132Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Turn off or restrict access to unneeded VB components.", "id": "relationship--0f27ea83-21e7-4a9f-9c66-85fe85da5135", "modified": "2026-04-29T14:23:05.924Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7471', 0, 38, '09-mitre-attack', 'retrieved', '7B1A38A9FC4F26AD062C56F102DDBE1232F2C51845644E5864B448E434090FF2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
