VALUES ('doc-09-mitre-attack-p0-7473', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-12T15:27:00.960Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable the WinRM service.", "id": "relationship--1677745c-06d5-4791-be9c-1104549c34b2", "modified": "2026-04-29T14:23:05.935Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--60d0c01d-e2bf-49dd-a453-f8a9c9fa6f65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7473', 0, 33, '09-mitre-attack', 'retrieved', '280919E1138F2E8D1D2963DFF2B316F73164C4A33BFCB56EC966A8F1651616A2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
