VALUES ('doc-09-mitre-attack-p0-7475', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-29T22:23:14.236Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable native virtualization technologies such as Hyper-V if not necessary within a given environment. Consider also disabling Windows Sandbox if it is not needed to test or debug applications.", "id": "relationship--1ec28c41-586b-42dc-9400-6e6313e38d84", "modified": "2026-04-29T14:23:05.946Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--b5327dd1-6bf9-4785-a199-25bcbd1f4a9d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7475', 0, 58, '09-mitre-attack', 'retrieved', '1E6DE03C1995D9BABE7FB95695113EF368B87D9959B24F5F0F3F4DBDBC73F2A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
