VALUES ('doc-09-mitre-attack-p0-7476', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-25T17:17:48.383Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable LLMNR, mDNS, and NetBIOS in local computer security settings or by group policy if they are not needed within an environment. (Citation: ADSecurity Windows Secure Baseline)", "external_references": [{"description": "Metcalf, S. (2016, October 21). Securing Windows Workstations: Developing a Secure Baseline. Retrieved November 17, 2017.", "source_name": "ADSecurity Windows Secure Baseline", "url": "https://adsecurity.org/?p=3299"}], "id": "relationship--2fb84998-3f4a-4ce8-9709-daa95d18186a", "modified": "2026-04-29T14:23:05.974Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--650c784b-7504-4df7-ab2c-4ea882384d1e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7476', 0, 81, '09-mitre-attack', 'retrieved', '273C512D0E09303BAD1655D5EF66F98C66A9435A8661687C24C4D877BD4369FE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
