VALUES ('doc-09-mitre-attack-p0-7477', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-25T12:25:23.800Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure that unnecessary ports and services are closed to prevent risk of discovery and potential exploitation.", "id": "relationship--32d482c4-2c0d-4688-a38b-d73b5b2962a3", "modified": "2026-04-29T14:23:05.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--e3a12395-188d-4051-9a16-ea8e14d07b88", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7477', 0, 45, '09-mitre-attack', 'retrieved', 'D8B1F9416C78D0CC85E3B2CE5759F8C856B99912C4A316D40DE6FA91FE7545B9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
