VALUES ('doc-09-mitre-attack-p0-7479', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-09T14:40:55.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable ClickOnce installations from the internet using the following registry key: \n`\\HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\.NETFramework\\Security\\TrustManager\\PromptingLevel — Internet:Disabled`(Citation: NetSPI ClickOnce)(Citation: Microsoft Learn ClickOnce Config)\n\nClickOnce may not be necessary within an environment and should be disabled if not being used.", "external_references": [{"description": "Microsoft. (2023, August 4). Configure the ClickOnce trust prompt behavior. Retrieved September 9, 2024.", "source_name": "Microsoft Learn ClickOnce Config", "url": "https://learn.microsoft.com/en-us/visualstudio/deployment/how-to-configure-the-clickonce-trust-prompt-behavior?view=vs-2022&tabs=csharp"}, {"description": "Ryan Gandrud. (2015, March 23). All You Need Is One – A ClickOnce Love Story. Retrieved September 9, 2024.", "source_name": "NetSPI ClickOnce", "url": "https://www.netspi.com/blog/technical-blog/adversary-simulation/all-you-need-is-one-a-clickonce-love-story/"}], "id": "relationship--336dc2ea-855a-4725-9112-b71739b95b58", "modified": "2026-04-29T14:23:05.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--cc279e50-df85-4c8e-be80-6dc2eda8849c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7479', 0, 112, '09-mitre-attack', 'retrieved', '51BF916AA91EEDE6A1E83EF6DE0EAFDB9D30FDB0903E06632D3EB87D4EF60EF5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
