VALUES ('doc-09-mitre-attack-p0-7480', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-06-15T18:39:46.919Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling external email forwarding.(Citation: Microsoft BEC Campaign)", "external_references": [{"description": "Carr, N., Sellmer, S. (2021, June 14). Behind the scenes of business email compromise: Using cross-domain threat data to disrupt a large BEC campaign. Retrieved June 15, 2021.", "source_name": "Microsoft BEC Campaign", "url": "https://www.microsoft.com/security/blog/2021/06/14/behind-the-scenes-of-business-email-compromise-using-cross-domain-threat-data-to-disrupt-a-large-bec-infrastructure/"}], "id": "relationship--38b2c8da-e69e-4e17-8ba9-c967d7af3a0a", "modified": "2026-04-29T14:23:05.997Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--7d77a07d-02fe-4e88-8bd9-e9c008c01bf0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7480', 0, 73, '09-mitre-attack', 'retrieved', '1B28F7EC490319986CD2255C72EF7C7CAA05928FC84BA4F783AB88AF93B2E216', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
