VALUES ('doc-09-mitre-attack-p0-7485', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-11T13:50:57.110Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable Autorun if it is unnecessary. (Citation: Microsoft Disable Autorun) Disallow or restrict removable media at an organizational policy level if they are not required for business operations. (Citation: TechNet Removable Media Control)", "external_references": [{"description": "Microsoft. (n.d.). How to disable the Autorun functionality in Windows. Retrieved April 20, 2016.", "source_name": "Microsoft Disable Autorun", "url": "https://support.microsoft.com/en-us/kb/967715"}, {"description": "Microsoft. (2007, August 31). https://technet.microsoft.com/en-us/library/cc771759(v=ws.10).aspx. Retrieved April 20, 2016.", "source_name": "TechNet Removable Media Control", "url": "https://technet.microsoft.com/en-us/library/cc772540(v=ws.10).aspx"}], "id": "relationship--553aadc2-8c1c-4ad7-b974-c65f99f6a892", "modified": "2026-04-29T14:23:06.041Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--a3e1e6c5-9c74-4fc0-a16c-a9d228c17829", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7485', 0, 101, '09-mitre-attack', 'retrieved', '926FCB3D9974D017FE56B7382823B406FEAFAF089ED0A3F5B2F1C3B42226D5CD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
