VALUES ('doc-09-mitre-attack-p0-7486', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-24T14:12:38.013Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling auto-mounting of disk image files (i.e., .iso, .img, .vhd, and .vhdx). This can be achieved by modifying the Registry values related to the Windows Explorer file associations in order to disable the automatic Explorer \"Mount and Burn\" dialog for these file extensions. Note: this will not deactivate the mount functionality itself.(Citation: GitHub MOTW)", "external_references": [{"description": "wdormann. (2019, August 29). Disable Windows Explorer file associations for Disc Image Mount. Retrieved April 16, 2022.", "source_name": "GitHub MOTW", "url": "https://gist.github.com/wdormann/fca29e0dcda8b5c0472e73e10c78c3e7"}], "id": "relationship--566db8cc-9dd7-496b-8d40-e510fcf6b9fe", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--7e7c2fba-7cca-486c-9582-4c1bb2851961", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7486', 0, 108, '09-mitre-attack', 'retrieved', '34FB81794F7E473DE3BC8BDD78C8165E3890A66CE3DE33EFA64AEBFF8347A921', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
