VALUES ('doc-09-mitre-attack-p0-7515', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-28T01:36:41.931Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "MMC may not be necessary within a given environment since it is primarily used by system administrators, not regular users or clients. ", "id": "relationship--ac005901-af89-4bcd-bb7f-515539dbb96c", "modified": "2026-04-29T14:23:06.159Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--ffbcfdb0-de22-4106-9ed3-fc23c8a01407", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7515', 0, 52, '09-mitre-attack', 'retrieved', '06E8A8B28B686A4A46D8B3B5754C3AC1D6FEB6AC1FC7FD357397528B4BF85A42', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
