VALUES ('doc-09-mitre-attack-p0-7517', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-24T15:15:13.613Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling emond by removing the [Launch Daemon](https://attack.mitre.org/techniques/T1543/004) plist file.", "id": "relationship--b02a8c2b-3ead-4546-9e68-d1545c5fcdd7", "modified": "2026-04-29T14:23:06.165Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--9c45eaa3-8604-4780-8988-b5074dbb9ecd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7517', 0, 39, '09-mitre-attack', 'retrieved', '958EA388C752D31C62A64335C59B7B2CD079B86B72ED45632541D365A2651617', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
