VALUES ('doc-09-mitre-attack-p0-7519', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-02T15:28:55.194Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If direct virtual machine connections are not required for administrative use, disable these connection types where feasible.", "id": "relationship--b4eefafe-e3d6-4b25-8485-7022c00cc462", "modified": "2026-04-29T14:23:06.172Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--45241b9e-9bbc-4826-a2cc-78855e51ca09", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7519', 0, 46, '09-mitre-attack', 'retrieved', '981A01934A8A4EAD2B0813B5214CCCD180A02924D815E0271DF4E9FFA49D4F6E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
