VALUES ('doc-09-mitre-attack-p0-7521', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-07-22T22:35:46.142Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling functions from web technologies such as PHP’s `evaI()` that may be abused for web shells.(Citation: ITSyndicate Disabling PHP functions)", "external_references": [{"description": "Kondratiev, A. (n.d.). Disabling dangerous PHP functions. Retrieved July 26, 2021.", "source_name": "ITSyndicate Disabling PHP functions", "url": "https://itsyndicate.org/blog/disabling-dangerous-php-functions/"}], "id": "relationship--c077dd0a-7568-400b-9aad-e0535f356f71", "modified": "2026-04-29T14:23:06.188Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7521', 0, 70, '09-mitre-attack', 'retrieved', '84C928DB13EF9B91291B7B02104ECECF9DE37DDC0F145D8F235FD902EA0F470B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
