VALUES ('doc-09-mitre-attack-p0-7522', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-16T20:04:52.503Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable Wake-on-LAN if it is not needed within an environment.", "id": "relationship--c2a79396-f264-4439-94f1-113e3bf3a6be", "modified": "2026-04-29T14:23:06.191Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--451a9977-d255-43c9-b431-66de80130c8c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7522', 0, 39, '09-mitre-attack', 'retrieved', 'D263D27FA9E927E5E5E5A660BE22697D003E70C231B02AD06009F92778A354D2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
