VALUES ('doc-09-mitre-attack-p0-7524', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-20T14:34:41.315Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Disable Autorun if it is unnecessary. (Citation: Microsoft Disable Autorun) Disallow or restrict removable media at an organizational policy level if they are not required for business operations. (Citation: TechNet Removable Media Control)", "external_references": [{"description": "Microsoft. (n.d.). How to disable the Autorun functionality in Windows. Retrieved April 20, 2016.", "source_name": "Microsoft Disable Autorun", "url": "https://support.microsoft.com/en-us/kb/967715"}, {"description": "Microsoft. (2007, August 31). https://technet.microsoft.com/en-us/library/cc771759(v=ws.10).aspx. Retrieved April 20, 2016.", "source_name": "TechNet Removable Media Control", "url": "https://technet.microsoft.com/en-us/library/cc772540(v=ws.10).aspx"}], "id": "relationship--c8ff6191-a8ac-4f12-b336-a2e0c7644082", "modified": "2026-04-29T14:23:06.200Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--e6415f09-df0e-48de-9aba-928c902b7549", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7524', 0, 101, '09-mitre-attack', 'retrieved', 'AFBC3539B8F2D48B7CC86EC3DE5A9D5B4C35E5A7B32F4C4394C210371CEFB381', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
