VALUES ('doc-09-mitre-attack-p0-7526', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-25T15:34:24.698Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling Microsoft Office macros/active content to prevent the execution of malicious payloads in documents (Citation: Microsoft Disable Macros), though this setting may not mitigate the [Forced Authentication](https://attack.mitre.org/techniques/T1187) use for this technique.", "external_references": [{"description": "Microsoft. (n.d.). Enable or disable macros in Office files. Retrieved September 13, 2018.", "source_name": "Microsoft Disable Macros", "url": "https://support.office.com/article/enable-or-disable-macros-in-office-files-12b036fd-d140-4e74-b45e-16fed1a7e5c6"}], "id": "relationship--cf485f42-cc2f-4ef7-9226-533192a9413c", "modified": "2026-04-29T14:23:06.209Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--dc31fe1e-d722-49da-8f5f-92c7b5aff534", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7526', 0, 82, '09-mitre-attack', 'retrieved', '4022840AF128E3F3CE9F6E3EC9313C9447D71EDC31A31A3F3B1FA8C49FE46EDA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
