INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-7527', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-09T13:17:39.429Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Registry keys specific to Microsoft Office feature control security can be set to disable automatic DDE/OLE execution. (Citation: Microsoft DDE Advisory Nov 2017)(Citation: BleepingComputer DDE Disabled in Word Dec 2017)(Citation: GitHub Disable DDEAUTO Oct 2017) Microsoft also created, and enabled by default, Registry keys to completely disable DDE execution in Word and Excel.(Citation: Microsoft ADV170021 Dec 2017)", "external_references": [{"description": "Microsoft. (2017, November 8). Microsoft Security Advisory 4053440 - Securely opening Microsoft Office documents that contain Dynamic Data Exchange (DDE) fields. Retrieved November 21, 2017.", "source_name": "Microsoft DDE Advisory Nov 2017", "url": "https://technet.microsoft.com/library/security/4053440"}, {"description": "Cimpanu, C. (2017, December 15). Microsoft Disables DDE Feature in Word to Prevent Further Malware Attacks. Retrieved December 19, 2017.", "source_name": "BleepingComputer DDE Disabled in Word Dec 2017", "url": "https://www.bleepingcomputer.com/news/microsoft/microsoft-disables-dde-feature-in-word-to-prevent-further-malware-attacks/"}, {"description": "Dormann, W. (2017, October 20). Disable DDEAUTO for Outlook, Word, OneNote, and Excel versions 2010, 2013, 2016. Retrieved February 3, 2018.", "source_name": "GitHub Disable DDEAUTO Oct 2017", "url": "https://gist.github.com/wdormann/732bb88d9b5dd5a66c9f1e1498f31a1b"}, {"description": "Microsoft. (2017, December 12). ADV170021 - Microsoft Office Defense in Depth Update. Retrieved February 3, 2018.", "source_name": "Microsoft ADV170021 Dec 2017", "url": "https://portal.msrc.microsoft.com/security-guidance/advisory/ADV170021"}], "id": "relationship--df52b929-6b31-48da-a21f-70b799e730d3", "modified": "2026-04-29T14:23:06.230Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--232a7e42-cd6e-4902-8fe9-2960f529dd4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7527', 0, 206, '09-mitre-attack', 'retrieved', '38F3788AAA39D27BA34BCED55D1BD91DFD4F828AF67C961C58361D66EB521C72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
