VALUES ('doc-09-mitre-attack-p0-7529', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T14:08:23.863Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "If email delegation is not required, disable it. In Google Workspace this can be accomplished through the Google Admin console.(Citation: Gmail Delegation)", "external_references": [{"description": "Google. (n.d.). Turn Gmail delegation on or off. Retrieved April 1, 2022.", "source_name": "Gmail Delegation", "url": "https://support.google.com/a/answer/7223765?hl=en"}], "id": "relationship--f212430d-160e-4676-b541-8a7cb818fe6f", "modified": "2026-04-29T14:23:06.254Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--e74de37c-a829-446c-937d-56a44f0e9306", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7529', 0, 70, '09-mitre-attack', 'retrieved', '12D51AFCE021CAD737B9F740E7E84C50A0E6743C9FDBAC39E8FC94ED214EF137', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
