VALUES ('doc-09-mitre-attack-p0-7530', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-21T16:52:53.740Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Specific developer utilities may not be necessary within a given environment and should be removed if not used.", "id": "relationship--f4e83a18-a2bf-45af-aa6b-18f72646d8b6", "modified": "2026-04-29T14:23:06.258Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--ff25900d-76d5-449b-a351-8824e62fc81b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7530', 0, 47, '09-mitre-attack', 'retrieved', 'CDCBD16911E143C82E22019FED9BC2BBB140AC08F99F381EA2FE8074F21DC6BE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
