VALUES ('doc-09-mitre-attack-p0-7532', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-03-14T17:48:36.425Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Consider disabling unnecessary remote connection functionality, including both unapproved software installations and specific features built into supported applications.", "id": "relationship--fa4c9d5a-3329-4138-b6e1-990cd7935b87", "modified": "2026-04-29T14:23:06.265Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--4061e78c-1284-44b4-9116-73e4ac3912f7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7532', 0, 47, '09-mitre-attack', 'retrieved', 'BAEFE01837A20F1D930F9848C40FB73CFE0FD20ECDC2A0A7F522FA307E5D3509', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
