VALUES ('doc-09-mitre-attack-p0-7533', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-28T18:43:00.826Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Remove unnecessary and potentially abusable authentication mechanisms where possible. For example, in Entra ID environments, disable the app password feature unless explicitly required. ", "id": "relationship--fb4099dc-c44a-49c4-b12e-5e58a5635bf4", "modified": "2026-04-29T14:23:06.266Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--8a2f40cf-8325-47f9-96e4-b1ca4c7389bd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7533', 0, 53, '09-mitre-attack', 'retrieved', 'BA655ADF71AAE5B1007515416E41FAD1D8911E2A1EA310D70194C5E678B4A2BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
