VALUES ('doc-09-mitre-attack-p0-7534', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-23T18:30:11.132Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "CMSTP.exe may not be necessary within a given environment (unless using it for VPN connection installation).", "id": "relationship--fd38c0fc-72d8-4638-b6e7-1f6c5964ab5c", "modified": "2026-04-29T14:23:06.269Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--eb88d97c-32f1-40be-80f0-d61a4b0b4b31", "spec_version": "2.1", "target_ref": "attack-pattern--4cbc6a62-9e34-4f94-8a19-5c1a11392a49", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7534', 0, 45, '09-mitre-attack', 'retrieved', '6421CC97534F247F3E4F24AA2A77A3F3C0A04567FC97C959AE59AA95E854A33B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
