VALUES ('doc-09-mitre-attack-p0-7537', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-07-01T20:18:35.306Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Where possible, consider restricting access to and use of serverless functions. For examples, conditional access policies can be applied to users attempting to create workflows in Microsoft Power Automate. Google Apps Scripts that use OAuth can be limited by restricting access to high-risk OAuth scopes.(Citation: Microsoft Developer Support Power Apps Conditional Access)(Citation: Google Workspace Apps Script Restrict OAuth Scopes)", "external_references": [{"description": "Google Workspace. (2024, March 5). Monitor & restrict data access. Retrieved July 1, 2024.", "source_name": "Google Workspace Apps Script Restrict OAuth Scopes", "url": "https://developers.google.com/apps-script/guides/admin/monitor-restrict-oauth-scopes"}, {"description": "Microsoft Developer Support. (2020, May 9). Control Access to Power Apps and Power Automate with Azure AD Conditional Access Policies. Retrieved July 1, 2024.", "source_name": "Microsoft Developer Support Power Apps Conditional Access", "url": "https://devblogs.microsoft.com/premier-developer/control-access-to-power-apps-and-power-automate-with-azure-ad-conditional-access-policies/"}], "id": "relationship--1790e922-4472-4509-8193-63ba613ce068", "modified": "2026-04-29T14:23:05.936Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--f9f9e6ef-bc0a-41ad-ba11-0924e5e84c4c", "spec_version": "2.1", "target_ref": "attack-pattern--e848506b-8484-4410-8017-3d235a52f5b3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7537', 0, 149, '09-mitre-attack', 'retrieved', 'B2462245F894784D9D6115C63EC4D983193799DDA660B0BBBCB045369E1BCD3D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
