VALUES ('doc-09-mitre-attack-p0-7538', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-10-16T17:43:35.505Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Where possible, consider restricting the use of access tokens outside of expected contexts. For example, in AWS environments, consider using data perimeters to prevent credential use outside of an expected network.(Citation: AWS Data Perimeters)", "external_references": [{"description": "AWS. (n.d.). Data perimeters on AWS. Retrieved October 16, 2024.", "source_name": "AWS Data Perimeters", "url": "https://aws.amazon.com/identity/data-perimeters-on-aws/"}], "id": "relationship--41f072bf-ec21-4a83-bb25-6c84fce8ca5d", "modified": "2026-04-29T14:23:06.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--f9f9e6ef-bc0a-41ad-ba11-0924e5e84c4c", "spec_version": "2.1", "target_ref": "attack-pattern--f005e783-57d4-4837-88ad-dbe7faee1c51", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7538', 0, 81, '09-mitre-attack', 'retrieved', '40085D80D220CB6BA3527986BC836F95533159B42636FD2280AD6D5A850C430F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
