VALUES ('doc-09-mitre-attack-p0-7539', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-15T15:41:44.140Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Adds verification for helpdesk resets, approvals, and app consents commonly targeted by impersonation.(Citation: SE SentinelOne 2)(Citation: SE - Hackers Target Workday)", "external_references": [{"description": "David Jones. (2025, August 19). Hackers target Workday in social engineering attack. Retrieved April 15, 2026.", "source_name": "SE - Hackers Target Workday", "url": "https://www.cybersecuritydive.com/news/hackers-target-workday-in-social-engineering-attack/758095/#:~:text=Researchers%20cite%20increasing%20evidence%20of,told%20Cybersecurity%20Dive%20via%20email."}, {"description": "SentinelOne. (2025, August 19). 15 Types of Social Engineering Attacks. Retrieved April 15, 2026.", "source_name": "SE SentinelOne 2", "url": "https://www.sentinelone.com/cybersecurity-101/threat-intelligence/types-of-social-engineering-attacks/"}], "id": "relationship--495350f1-94f1-4a31-916f-3f449b4af12e", "modified": "2026-04-29T14:23:06.025Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--f9f9e6ef-bc0a-41ad-ba11-0924e5e84c4c", "spec_version": "2.1", "target_ref": "attack-pattern--41e4d77a-6275-4976-9e35-785985598519", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7539', 0, 97, '09-mitre-attack', 'retrieved', '6ABA8153F6C695FE46867F3B9E421405FC0764708558EA4B1F278882CAF8A07C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
