VALUES ('doc-09-mitre-attack-p0-7540', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-20T17:27:40.285Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Set account lockout policies after a certain number of failed login attempts to prevent passwords from being guessed. Too strict a policy may create a denial of service condition and render environments un-usable, with all accounts used in the brute force being locked-out. Use conditional access policies to block logins from non-compliant devices or from outside defined organization IP ranges.(Citation: Microsoft Common Conditional Access Policies) Consider blocking risky authentication requests, such as those originating from anonymizing services/proxies.(Citation: Okta Block Anonymizing Services)", "external_references": [{"description": "Microsoft. (2022, December 14). Conditional Access templates. Retrieved February 21, 2023.", "source_name": "Microsoft Common Conditional Access Policies", "url": "https://learn.microsoft.com/en-us/azure/active-directory/conditional-access/concept-conditional-access-policy-common"}, {"description": "Moussa Diallo and Brett Winterford. (2024, April 26). How to Block Anonymizing Services using Okta. Retrieved May 28, 2024.", "source_name": "Okta Block Anonymizing Services", "url": "https://sec.okta.com/blockanonymizers"}], "id": "relationship--4b7e0525-1ba7-4d55-89d1-07fc94193065", "modified": "2026-04-29T14:23:06.028Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--f9f9e6ef-bc0a-41ad-ba11-0924e5e84c4c", "spec_version": "2.1", "target_ref": "attack-pattern--b2d03cea-aec1-45ca-9744-9ee583c1e1cc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7540', 0, 158, 