VALUES ('doc-09-mitre-attack-p0-7543', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-01T02:15:49.915Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Enable account restrictions to prevent login attempts, and the subsequent 2FA/MFA service requests, from being initiated from suspicious locations or when the source of the login attempts do not match the location of the 2FA/MFA smart device. Use conditional access policies to block logins from non-compliant devices or from outside defined organization IP ranges.(Citation: Microsoft Common Conditional Access Policies)", "external_references": [{"description": "Microsoft. (2022, December 14). Conditional Access templates. Retrieved February 21, 2023.", "source_name": "Microsoft Common Conditional Access Policies", "url": "https://learn.microsoft.com/en-us/azure/active-directory/conditional-access/concept-conditional-access-policy-common"}], "id": "relationship--a09cb233-bdff-4d89-bcc3-7fb2108911d0", "modified": "2026-04-29T14:23:06.144Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--f9f9e6ef-bc0a-41ad-ba11-0924e5e84c4c", "spec_version": "2.1", "target_ref": "attack-pattern--954a1639-f2d6-407d-aef3-4917622ca493", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7543', 0, 109, '09-mitre-attack', 'retrieved', '3FE7F5CDB3902171DF8DAC285F3CF8B8BB2EB22008E72BCF45FB081C3030580C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
