VALUES ('doc-09-mitre-attack-p0-7556', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-10-05T02:15:30.004Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encrypt data stored at rest in cloud storage.(Citation: Amazon S3 Security, 2019)(Citation: Microsoft Azure Storage Security, 2019) Managed encryption keys can be rotated by most providers. At a minimum, ensure an incident response plan to storage breach includes rotating the keys and test for impact on client applications.(Citation: Google Cloud Encryption Key Rotation)", "external_references": [{"description": "Amazon. (2019, May 17). How can I secure the files in my Amazon S3 bucket?. Retrieved October 4, 2019.", "source_name": "Amazon S3 Security, 2019", "url": "https://aws.amazon.com/premiumsupport/knowledge-center/secure-s3-resources/"}, {"description": "Amlekar, M., Brooks, C., Claman, L., et. al.. (2019, March 20). Azure Storage security guide. Retrieved October 4, 2019.", "source_name": "Microsoft Azure Storage Security, 2019", "url": "https://docs.microsoft.com/en-us/azure/storage/common/storage-security-guide"}, {"description": "Google. (n.d.). Key rotation. Retrieved October 18, 2019.", "source_name": "Google Cloud Encryption Key Rotation", "url": "https://cloud.google.com/kms/docs/key-rotation"}], "id": "relationship--55fa32b7-b9d2-4c57-9614-b7793b2770f2", "modified": "2026-04-29T14:23:06.043Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--3298ce88-1628-43b1-87d9-0b5336b193d7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7556', 0, 155, '09-mitre-attack', 'retrieved', 'EC89135858B4F19