VALUES ('doc-09-mitre-attack-p0-7559', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-19T18:52:25.314Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of encryption provides an added layer of security to sensitive information sent over email. Encryption using public key cryptography requires the adversary to obtain the private certificate along with an encryption key to decrypt messages.", "id": "relationship--8178dba2-1469-4322-af59-f6935152deb0", "modified": "2026-04-29T14:23:06.102Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--b4694861-542c-48ea-9eb1-10d356e7140a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7559', 0, 65, '09-mitre-attack', 'retrieved', 'CD85D362431FB24B4D349AAB2FE56644BF02E1DF0CF57B35DC820D43F2249252', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
