VALUES ('doc-09-mitre-attack-p0-7561', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-28T17:05:15.045Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Obfuscate/encrypt event files locally and in transit to avoid giving feedback to an adversary.", "id": "relationship--8fdfaa48-8004-4b46-a5f6-a5f6a1bac593", "modified": "2026-04-29T14:23:06.121Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--75b9a4d2-d4e2-4ca1-9aab-1badd9e05fd0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7561', 0, 43, '09-mitre-attack', 'retrieved', '81B6011BC4F2BE2B2AF1BB5377C0416AD99B809052911AF02A038C4B8BEEEB01', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
