VALUES ('doc-09-mitre-attack-p0-7562', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-06-13T16:43:15.017Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Encryption and off-system storage of sensitive information may be one way to mitigate collection of files, but may not stop an adversary from acquiring the information if an intrusion persists over a long period of time and the adversary is able to discover and access the data through other means. Strong passwords should be used on certain encrypted documents that use them to prevent offline cracking through [Brute Force](https://attack.mitre.org/techniques/T1110) techniques.", "id": "relationship--967c7069-6bb3-4f10-ba6b-5befdabe6c97", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7562', 0, 99, '09-mitre-attack', 'retrieved', 'EB2B699C2DA9E45A609B52381F9C3235F8DF547C0DD97D6112451510DDD7B157', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
