VALUES ('doc-09-mitre-attack-p0-7572', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-21T17:31:33.869Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure Domain Controller backups are properly secured.(Citation: Metcalf 2015)", "external_references": [{"description": "Metcalf, S. (2015, January 19). Attackers Can Now Use Mimikatz to Implant Skeleton Key on Domain Controllers & BackDoor Your Active Directory Forest. Retrieved February 3, 2015.", "source_name": "Metcalf 2015", "url": "http://adsecurity.org/?p=1275"}], "id": "relationship--e6b41083-5390-452d-991c-de86befbe6e1", "modified": "2026-04-29T14:23:06.239Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--edf91964-b26e-4b4a-9600-ccacd7d7df24", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7572', 0, 72, '09-mitre-attack', 'retrieved', '27BF84AA046C6F0245FDE65C8FC328883C4A44B4B547B2BAE0A325161E9166EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
