VALUES ('doc-09-mitre-attack-p0-7573', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-04T13:06:49.703Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When possible, store keys on separate cryptographic hardware instead of on the local system. For example, on Windows systems use a TPM to secure keys and other sensitive credential material.(Citation: Microsoft Primary Refresh Token)", "external_references": [{"description": "Microsoft. (2022, September 9). What is a Primary Refresh Token?. Retrieved February 21, 2023.", "source_name": "Microsoft Primary Refresh Token", "url": "https://learn.microsoft.com/en-us/azure/active-directory/devices/concept-primary-refresh-token"}], "id": "relationship--ee382a02-cde0-49a8-89e2-26237a25740c", "modified": "2026-04-29T14:23:06.249Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7573', 0, 86, '09-mitre-attack', 'retrieved', 'DF4FBA88A38209CF4866BE1F63E4CA69DF2C4F1B1C58F2B3B361CDD38D744D72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
