VALUES ('doc-09-mitre-attack-p0-7574', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-01-30T17:37:22.734Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "File encryption should be enforced across email communications containing sensitive information that may be obtained through access to email services.", "id": "relationship--efafd777-c53d-4459-8765-2e5e44cd0ea1", "modified": "2026-04-29T14:23:06.251Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--f005e783-57d4-4837-88ad-dbe7faee1c51", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7574', 0, 49, '09-mitre-attack', 'retrieved', '5D3C29FF9265D4882524C21D21AE5E6098863CD2D959C51AC52DDFCEC668CE95', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
