VALUES ('doc-09-mitre-attack-p0-7575', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-02-19T18:46:06.853Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Use of encryption provides an added layer of security to sensitive information sent over email. Encryption using public key cryptography requires the adversary to obtain the private certificate along with an encryption key to decrypt messages.", "id": "relationship--f5d32cc0-dc9e-4ff4-8af2-b131c303a1a1", "modified": "2026-04-29T14:23:06.259Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--1e9eb839-294b-48cc-b0d3-c45555a2a004", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7575', 0, 65, '09-mitre-attack', 'retrieved', '75FC4AA0D9D8C00B9F53507A53BD924305E114D05C032A8054DFCE3A4FB3340D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
