VALUES ('doc-09-mitre-attack-p0-7578', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-03T03:29:06.961Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Ensure certificates as well as associated private keys are appropriately secured. Consider utilizing additional hardware credential protections such as trusted platform modules (TPM) or hardware security modules (HSM). Enforce HTTPS and enable Extended Protection for\nAuthentication.(Citation: SpecterOps Certified Pre Owned)", "external_references": [{"description": "Schroeder, W. & Christensen, L. (2021, June 22). Certified Pre-Owned - Abusing Active Directory Certificate Services. Retrieved August 2, 2022.", "source_name": "SpecterOps Certified Pre Owned", "url": "https://web.archive.org/web/20220818094600/https://specterops.io/assets/resources/Certified_Pre-Owned.pdf"}], "id": "relationship--98b6508c-5f00-4c06-a906-4fd7ce74bc62", "modified": "2026-08-04T20:30:55.342Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "mitigates", "revoked": false, "source_ref": "course-of-action--feff9142-e8c2-46f4-842b-bd6fb3d41157", "spec_version": "2.1", "target_ref": "attack-pattern--7de1f7ac-5d0c-4c9c-8873-627202205331", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7578', 0, 97, '09-mitre-attack', 'retrieved', '9F34879F0E5BEA3F9CEEA84B6AE76412D1774E33F346F2EE815864C56D75558A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
