VALUES ('doc-09-mitre-attack-p0-7580', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-22T21:57:04.271Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT38](https://attack.mitre.org/groups/G0082) has injected malicious payloads into the `explorer.exe` process.(Citation: 1 - appv) ", "external_references": [{"description": "SEONGSU PARK. (2022, December 27). BlueNoroff introduces new methods bypassing MoTW. Retrieved February 6, 2024.", "source_name": "1 - appv", "url": "https://securelist.com/bluenoroff-methods-bypass-motw/108383/"}], "id": "relationship--0321e766-10c1-4215-9fd6-7f712b642dca", "modified": "2026-07-31T20:48:23.015Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--00f67a77-86a4-4adf-be26-1a54fc713340", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7580', 0, 65, '09-mitre-attack', 'retrieved', 'B8909E045BBF5D92270CFFDAD3180C59C350272CF659D7D36A24C90EB44BAF15', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
