VALUES ('doc-09-mitre-attack-p0-7581', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-29T22:24:15.758Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT38](https://attack.mitre.org/groups/G0082) has identified primary users, currently logged in users, sets of users that commonly use a system, or inactive users.(Citation: CISA AA20-239A BeagleBoyz August 2020)", "external_references": [{"description": "DHS/CISA. (2020, August 26). FASTCash 2.0: North Korea''s BeagleBoyz Robbing Banks. Retrieved September 29, 2021.", "source_name": "CISA AA20-239A BeagleBoyz August 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-239a"}], "id": "relationship--064cfeb5-9ddb-4dd2-ada4-cf9e65601dc5", "modified": "2026-07-31T20:48:23.023Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--00f67a77-86a4-4adf-be26-1a54fc713340", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7581', 0, 79, '09-mitre-attack', 'retrieved', '8FA3E1138BB1B588D13EB1F263B491132E724E46B9D9B9D36D5179575A9D034B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
