VALUES ('doc-09-mitre-attack-p0-7585', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:27:25.235Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT38](https://attack.mitre.org/groups/G0082) has used a utility called CLOSESHAVE that can securely delete a file from the system. They have also removed malware, tools, or other non-native files used during the intrusion to reduce their footprint or as part of the post-intrusion cleanup process.(Citation: FireEye APT38 Oct 2018)(Citation: CISA AA20-239A BeagleBoyz August 2020)", "external_references": [{"description": "DHS/CISA. (2020, August 26). FASTCash 2.0: North Korea''s BeagleBoyz Robbing Banks. Retrieved September 29, 2021.", "source_name": "CISA AA20-239A BeagleBoyz August 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-239a"}, {"description": "FireEye. (2018, October 03). APT38: Un-usual Suspects. Retrieved November 17, 2024.", "source_name": "FireEye APT38 Oct 2018", "url": "https://services.google.com/fh/files/misc/apt38-un-usual-suspects.pdf"}], "id": "relationship--161225df-de21-4715-b4f3-c324c05ff590", "modified": "2026-07-31T20:48:23.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--00f67a77-86a4-4adf-be26-1a54fc713340", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7585', 0, 124, '09-mitre-attack', 'retrieved', '1747517363156C1630980731ECF0437C66CAB04232FDF8A59880A05EF21D77F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
