VALUES ('doc-09-mitre-attack-p0-7617', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-29T22:24:15.706Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT38](https://attack.mitre.org/groups/G0082) has prepended a space to all of their terminal commands to operate without leaving traces in the HISTCONTROL environment.(Citation: CISA AA20-239A BeagleBoyz August 2020)", "external_references": [{"description": "DHS/CISA. (2020, August 26). FASTCash 2.0: North Korea''s BeagleBoyz Robbing Banks. Retrieved September 29, 2021.", "source_name": "CISA AA20-239A BeagleBoyz August 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-239a"}], "id": "relationship--9ea5c70d-6f04-4530-925a-5fa0c3521b79", "modified": "2026-07-31T20:48:23.311Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--00f67a77-86a4-4adf-be26-1a54fc713340", "spec_version": "2.1", "target_ref": "attack-pattern--b831f51c-d22f-4724-bbab-60d056bd1150", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7617', 0, 79, '09-mitre-attack', 'retrieved', '50ABCEA5497727A8E82AFF3166C41489ED4C43B2D414B11E3AFDE45FA66CFDBB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
