VALUES ('doc-09-mitre-attack-p0-7618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-29T20:46:38.432Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT38](https://attack.mitre.org/groups/G0082) has used Task Scheduler to run programs at system startup or on a scheduled basis for persistence.(Citation: CISA AA20-239A BeagleBoyz August 2020) Additionally, [APT38](https://attack.mitre.org/groups/G0082) has used living-off-the-land scripts to execute a malicious script via a scheduled task.(Citation: 1 - appv) ", "external_references": [{"description": "DHS/CISA. (2020, August 26). FASTCash 2.0: North Korea''s BeagleBoyz Robbing Banks. Retrieved September 29, 2021.", "source_name": "CISA AA20-239A BeagleBoyz August 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-239a"}, {"description": "SEONGSU PARK. (2022, December 27). BlueNoroff introduces new methods bypassing MoTW. Retrieved February 6, 2024.", "source_name": "1 - appv", "url": "https://securelist.com/bluenoroff-methods-bypass-motw/108383/"}], "id": "relationship--a3157c50-410e-4218-8707-326ab0146c94", "modified": "2026-07-31T20:48:23.318Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--00f67a77-86a4-4adf-be26-1a54fc713340", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7618', 0, 118, '09-mitre-attack', 'retrieved', 'A209C145FB0BE3D43FAC38DE8C731F8501D103F85B5F48D3DC56DAA9A867894A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
