VALUES ('doc-09-mitre-attack-p0-7646', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-03T18:16:29.820Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Indrik Spider](https://attack.mitre.org/groups/G0119) has purchased access to victim VPNs to facilitate access to victim environments.(Citation: Mandiant_UNC2165) ", "external_references": [{"description": "Mandiant Intelligence. (2022, June 2). To HADES and Back: UNC2165 Shifts to LOCKBIT to Evade Sanctions. Retrieved July 29, 2024.", "source_name": "Mandiant_UNC2165", "url": "https://cloud.google.com/blog/topics/threat-intelligence/unc2165-shifts-to-evade-sanctions/"}], "id": "relationship--451d0efa-51c0-414b-a839-cb44edca7bdc", "modified": "2026-07-31T18:47:35.346Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--01e28736-2ffc-455b-9880-ed4d1407ae07", "spec_version": "2.1", "target_ref": "attack-pattern--0458aab9-ad42-4eac-9e22-706a95bafee2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7646', 0, 71, '09-mitre-attack', 'retrieved', '0BCD007797FD1F4429B38049C5160A782FD077F11B8F88E63643BA3624482FF0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
