VALUES ('doc-09-mitre-attack-p0-7662', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-03T16:38:03.901Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Indrik Spider](https://attack.mitre.org/groups/G0119) has used valid accounts for initial access and lateral movement.(Citation: Mandiant_UNC2165) [Indrik Spider](https://attack.mitre.org/groups/G0119) has also maintained access to the victim environment through the VPN infrastructure.(Citation: Mandiant_UNC2165)", "external_references": [{"description": "Mandiant Intelligence. (2022, June 2). To HADES and Back: UNC2165 Shifts to LOCKBIT to Evade Sanctions. Retrieved July 29, 2024.", "source_name": "Mandiant_UNC2165", "url": "https://cloud.google.com/blog/topics/threat-intelligence/unc2165-shifts-to-evade-sanctions/"}], "id": "relationship--8f0596f7-159c-43c0-a848-cffb02fc3c9e", "modified": "2026-07-31T18:47:35.716Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--01e28736-2ffc-455b-9880-ed4d1407ae07", "spec_version": "2.1", "target_ref": "attack-pattern--b17a1a56-e99c-403c-8948-561df0cffe81", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7662', 0, 83, '09-mitre-attack', 'retrieved', 'C54FB998D4491C202FA451B136AB730FF6BCF5131128B00B7E1188455D5147C2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
