VALUES ('doc-09-mitre-attack-p0-7664', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-02-08T21:58:15.830Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Indrik Spider](https://attack.mitre.org/groups/G0119) has encrypted domain-controlled systems using [BitPaymer](https://attack.mitre.org/software/S0570).(Citation: Crowdstrike Indrik November 2018) Additionally, [Indrik Spider](https://attack.mitre.org/groups/G0119) used [PsExec](https://attack.mitre.org/software/S0029) to execute a ransomware script.(Citation: Mandiant_UNC2165)", "external_references": [{"description": "Frankoff, S., Hartley, B. (2018, November 14). Big Game Hunting: The Evolution of INDRIK SPIDER From Dridex Wire Fraud to BitPaymer Targeted Ransomware. Retrieved January 6, 2021.", "source_name": "Crowdstrike Indrik November 2018", "url": "https://www.crowdstrike.com/blog/big-game-hunting-the-evolution-of-indrik-spider-from-dridex-wire-fraud-to-bitpaymer-targeted-ransomware/"}, {"description": "Mandiant Intelligence. (2022, June 2). To HADES and Back: UNC2165 Shifts to LOCKBIT to Evade Sanctions. Retrieved July 29, 2024.", "source_name": "Mandiant_UNC2165", "url": "https://cloud.google.com/blog/topics/threat-intelligence/unc2165-shifts-to-evade-sanctions/"}], "id": "relationship--a5ee5826-e742-4847-9816-d9124827262a", "modified": "2026-07-31T18:47:35.777Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--01e28736-2ffc-455b-9880-ed4d1407ae07", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7664', 0, 113, '09-mitre-attack', 'retrieved', '513372B9643A8A2D86DC499ECF11DA32881ECA5B33F43361530B7A24