VALUES ('doc-09-mitre-attack-p0-7816', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-07-19T17:27:02.530Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GALLIUM](https://attack.mitre.org/groups/G0093) used a modified version of [NBTscan](https://attack.mitre.org/software/S0590) to identify available NetBIOS name servers over the network as well as ping to identify remote systems.(Citation: Cybereason Soft Cell June 2019)", "external_references": [{"description": "Cybereason Nocturnus. (2019, June 25). Operation Soft Cell: A Worldwide Campaign Against Telecommunications Providers. Retrieved July 18, 2019.", "source_name": "Cybereason Soft Cell June 2019", "url": "https://www.cybereason.com/blog/operation-soft-cell-a-worldwide-campaign-against-telecommunications-providers"}], "id": "relationship--ea71022e-7f2a-4065-9cb1-304f85dbaf6d", "modified": "2026-07-31T18:47:37.616Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--06a11b7e-2a36-47fe-8d3e-82c265df3258", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7816', 0, 86, '09-mitre-attack', 'retrieved', 'C4BD77877A934DA607C3BFF62483F71ABE149B6B809625E799E548A24CE6FF17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
