VALUES ('doc-09-mitre-attack-p0-7821', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.060Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: FireEye APT17)", "external_references": [{"description": "FireEye Labs/FireEye Threat Intelligence. (2015, May 14). Hiding in Plain Sight: FireEye and Microsoft Expose Obfuscation Tactic. Retrieved November 17, 2024.", "source_name": "FireEye APT17", "url": "https://web.archive.org/web/20240119213200/https://www2.fireeye.com/rs/fireye/images/APT17_Report.pdf"}], "id": "relationship--a33388b7-3803-442f-8e31-511eef055470", "modified": "2026-07-31T18:47:37.345Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--090242d7-73fc-4738-af68-20162f7a5aae", "spec_version": "2.1", "target_ref": "malware--d69c8146-ab35-4d50-8382-6fc80e641d43", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7821', 0, 60, '09-mitre-attack', 'retrieved', 'B5E523B5E29B74D54A861D824CB694EEDF6AE00530B5ECB92F40171A6FAB567D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
