VALUES ('doc-09-mitre-attack-p0-7822', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-13T22:33:14.133Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT17](https://attack.mitre.org/groups/G0025) has created and cultivated profile pages in Microsoft TechNet. To make profile pages appear more legitimate, [APT17](https://attack.mitre.org/groups/G0025) has created biographical sections and posted in forum threads.(Citation: FireEye APT17)", "external_references": [{"description": "FireEye Labs/FireEye Threat Intelligence. (2015, May 14). Hiding in Plain Sight: FireEye and Microsoft Expose Obfuscation Tactic. Retrieved November 17, 2024.", "source_name": "FireEye APT17", "url": "https://web.archive.org/web/20240119213200/https://www2.fireeye.com/rs/fireye/images/APT17_Report.pdf"}], "id": "relationship--fd9834dc-0323-408b-b217-3f3aa27b50ac", "modified": "2026-07-31T18:47:37.362Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--090242d7-73fc-4738-af68-20162f7a5aae", "spec_version": "2.1", "target_ref": "attack-pattern--cdfc5f0a-9bb9-4352-b896-553cfa2d8fd8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7822', 0, 86, '09-mitre-attack', 'retrieved', '1EE8B51F8BE983080B66AE0BD9ECEAEAD7B04E588816558DBF63B018E98DFE40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
