VALUES ('doc-09-mitre-attack-p0-7823', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.056Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An [APT3](https://attack.mitre.org/groups/G0022) downloader creates persistence by creating the following scheduled task: schtasks /create /tn \"mysc\" /tr C:\\Users\\Public\\test.exe /sc ONLOGON /ru \"System\" .(Citation: FireEye Operation Double Tap)", "external_references": [{"description": "Moran, N., et al. (2014, November 21). Operation Double Tap. Retrieved January 14, 2016.", "source_name": "FireEye Operation Double Tap", "url": "https://www.fireeye.com/blog/threat-research/2014/11/operation_doubletap.html"}], "id": "relationship--0ca1948b-476c-4ff5-a792-f3790250bdc1", "modified": "2026-07-31T18:47:37.620Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0bbdf25b-30ff-4894-a1cd-49260d0dd2d9", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7823', 0, 78, '09-mitre-attack', 'retrieved', '118F344E5AB7C2E407CABA4F95E737C7D134ED4051E1D928E37205B5A4308F12', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
