VALUES ('doc-09-mitre-attack-p0-7824', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.056Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An [APT3](https://attack.mitre.org/groups/G0022) downloader first establishes a SOCKS5 connection to 192.157.198[.]103 using TCP port 1913; once the server response is verified, it then requests a connection to 192.184.60[.]229 on TCP port 81.(Citation: FireEye Operation Double Tap)", "external_references": [{"description": "Moran, N., et al. (2014, November 21). Operation Double Tap. Retrieved January 14, 2016.", "source_name": "FireEye Operation Double Tap", "url": "https://www.fireeye.com/blog/threat-research/2014/11/operation_doubletap.html"}], "id": "relationship--1258536b-6cf4-4cfe-98c7-e9c1d30c5a34", "modified": "2026-07-31T18:47:37.634Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0bbdf25b-30ff-4894-a1cd-49260d0dd2d9", "spec_version": "2.1", "target_ref": "attack-pattern--84e02621-8fdf-470f-bd58-993bb6a89d91", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7824', 0, 87, '09-mitre-attack', 'retrieved', '083DFCE5BDADC03F8C61B412580CFED98002FCEAAD721AE605898FE0EE9E0BFE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
