VALUES ('doc-09-mitre-attack-p0-7825', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-01-16T21:43:14.128Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT3](https://attack.mitre.org/groups/G0022) has been known to brute force password hashes to be able to leverage plain text credentials.(Citation: APT3 Adversary Emulation Plan)", "external_references": [{"description": "Korban, C, et al. (2017, September). APT3 Adversary Emulation Plan. Retrieved January 16, 2018.", "source_name": "APT3 Adversary Emulation Plan", "url": "https://attack.mitre.org/docs/APT3_Adversary_Emulation_Plan.pdf"}], "id": "relationship--1334cbe3-8613-4279-9a1f-58781c2656a4", "modified": "2026-07-31T18:47:37.651Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0bbdf25b-30ff-4894-a1cd-49260d0dd2d9", "spec_version": "2.1", "target_ref": "attack-pattern--1d24cdee-9ea2-4189-b08e-af110bf2435d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7825', 0, 73, '09-mitre-attack', 'retrieved', '5AEE1E776A15C132247E66321091C64919B65E5951A0F5D76864F163BF4F3668', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
