VALUES ('doc-09-mitre-attack-p0-7831', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.056Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An [APT3](https://attack.mitre.org/groups/G0022) downloader uses the Windows command \"cmd.exe\" /C whoami . The group also uses a tool to execute commands on remote computers.(Citation: FireEye Operation Double Tap)(Citation: Symantec Buckeye)", "external_references": [{"description": "Moran, N., et al. (2014, November 21). Operation Double Tap. Retrieved January 14, 2016.", "source_name": "FireEye Operation Double Tap", "url": "https://www.fireeye.com/blog/threat-research/2014/11/operation_doubletap.html"}, {"description": "Symantec Security Response. (2016, September 6). Buckeye cyberespionage group shifts gaze from US to Hong Kong. Retrieved September 26, 2016.", "source_name": "Symantec Buckeye", "url": "https://web.archive.org/web/20160910124439/http://www.symantec.com/connect/blogs/buckeye-cyberespionage-group-shifts-gaze-us-hong-kong"}], "id": "relationship--41d61146-4a42-4897-b4a1-a706130a322d", "modified": "2026-07-31T18:47:37.757Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0bbdf25b-30ff-4894-a1cd-49260d0dd2d9", "spec_version": "2.1", "target_ref": "attack-pattern--d1fcf083-a721-4223-aedf-bf8960798d62", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7831', 0, 107, '09-mitre-attack', 'retrieved', 'E86EDF29C525ABE0F1AA9195137E1917F3682E5662331739E50603C005DCA9F2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
