VALUES ('doc-09-mitre-attack-p0-7873', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-12-06T19:12:47.449Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Mustard Tempest](https://attack.mitre.org/groups/G1020) has posted false advertisements including for software packages and browser updates in order to distribute malware.(Citation: Microsoft Ransomware as a Service)", "external_references": [{"description": "Microsoft. (2022, May 9). Ransomware as a service: Understanding the cybercrime gig economy and how to protect yourself. Retrieved March 10, 2023.", "source_name": "Microsoft Ransomware as a Service", "url": "https://www.microsoft.com/en-us/security/blog/2022/05/09/ransomware-as-a-service-understanding-the-cybercrime-gig-economy-and-how-to-protect-yourself/"}], "id": "relationship--04200684-0886-4299-ac13-f2c59c3b47d9", "modified": "2026-07-31T18:47:37.682Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0d4ac089-ced4-4cc4-a989-174d08e6d030", "spec_version": "2.1", "target_ref": "attack-pattern--155207c0-7f53-4f13-a06b-0a9907ef5096", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7873', 0, 84, '09-mitre-attack', 'retrieved', '7E302D42B28F665B871210B918660A6BEDAB9A57F0A41C05B29EC9DB32BB1811', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
