VALUES ('doc-09-mitre-attack-p0-7893', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-17T23:18:03.085Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Troll Stealer](https://attack.mitre.org/software/S1196) is exclusively linked to [Kimsuky](https://attack.mitre.org/groups/G0094) operations.(Citation: S2W Troll Stealer 2024)(Citation: Symantec Troll Stealer 2024)(Citation: ASEC Troll Stealer 2024)", "external_references": [{"description": "AhnLab ASEC. (2024, February 16). TrollAgent That Infects Systems Upon Security Program Installation Process (Kimsuky Group). Retrieved January 17, 2025.", "source_name": "ASEC Troll Stealer 2024", "url": "https://asec.ahnlab.com/en/61934/"}, {"description": "Jiho Kim & Sebin Lee, S2W. (2024, February 7). Kimsuky disguised as a Korean company signed with a valid certificate to distribute Troll Stealer (English ver.). Retrieved January 17, 2025.", "source_name": "S2W Troll Stealer 2024", "url": "https://medium.com/s2wblog/kimsuky-disguised-as-a-korean-company-signed-with-a-valid-certificate-to-distribute-troll-stealer-cfa5d54314e2"}, {"description": "Symantec Threat Hunter Team. (2024, May 16). Springtail: New Linux Backdoor Added to Toolkit. Retrieved January 17, 2025.", "source_name": "Symantec Troll Stealer 2024", "url": "https://www.security.com/threat-intelligence/springtail-kimsuky-backdoor-espionage"}], "id": "relationship--082cf8c1-a63c-4719-b0b0-60f28102f29b", "modified": "2026-07-31T20:48:24.412Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "malware--d6748457-75c2-4989-a41f-2d017994057e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre