VALUES ('doc-09-mitre-attack-p0-7908', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T01:01:36.376Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has leveraged ClickFix type tactics enticing victims to copy and paste malicious code.(Citation: NaumaanProofpoint_GlobalClickFix_April2025)", "external_references": [{"description": "Naumaan, S., et al. (2025, April 17). Around the World in 90 Days: State-Sponsored Actors Try ClickFix . Retrieved January 21, 2026.", "source_name": "NaumaanProofpoint_GlobalClickFix_April2025", "url": "https://www.proofpoint.com/us/blog/threat-insight/around-world-90-days-state-sponsored-actors-try-clickfix"}], "id": "relationship--1cfceb58-4433-45c0-bbd8-8c69de3bc24a", "modified": "2026-07-31T20:48:24.550Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--e261a979-f354-41a8-963e-6cadac27c4bf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7908', 0, 72, '09-mitre-attack', 'retrieved', '37C21653E6E7F12B2062BBD16B6201FF8D77BED6E8AC314044B8050587567D97', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
