VALUES ('doc-09-mitre-attack-p0-7915', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-19T00:58:33.855Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has also impersonated legitimate people, such as a foreign advisor, an embassy employee, and a think tank employee.(Citation: FBI_KimsukyQR_Jan2026) [Kimsuky](https://attack.mitre.org/groups/G0094) has also purported to be a Japanese diplomat to communicate with the victims.(Citation: NaumaanProofpoint_GlobalClickFix_April2025)", "external_references": [{"description": "FBI. (2026, January 8). FBI Flash AC-000001-MW North Korean Kimsuky Actors Leverage Malicious QR Codes in Spearphishing Campaigns Targeting U.S. Entities. Retrieved April 18, 2026.", "source_name": "FBI_KimsukyQR_Jan2026", "url": "https://www.ic3.gov/CSA/2026/260108.pdf"}, {"description": "Naumaan, S., et al. (2025, April 17). Around the World in 90 Days: State-Sponsored Actors Try ClickFix . Retrieved January 21, 2026.", "source_name": "NaumaanProofpoint_GlobalClickFix_April2025", "url": "https://www.proofpoint.com/us/blog/threat-insight/around-world-90-days-state-sponsored-actors-try-clickfix"}], "id": "relationship--21f3796d-3dd7-4b43-bd80-ec75ef3edfef", "modified": "2026-07-31T20:48:24.605Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--cd92d2b8-ce43-4666-9472-f1b4b9f4f8be", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7915', 0, 122, '09-mitre-attack', 'retrieved', '1C1B6B67C7CDF27BDC816D59148D56D06433FF95A85840D0A6BFF3269B791A41', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
