VALUES ('doc-09-mitre-attack-p0-7931', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-18T21:33:11.761Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has obfuscated code within files by converting hexadecimal strings to decimal numbers using the `CLng function` in combination with processing arithmetic operations and leveraging the `Chr function` to generate readable characters.(Citation: Aryaka Kimsuky July 2025) [Kimsuky](https://attack.mitre.org/groups/G0094) has also encoded files with Base64 and RC4.(Citation: Aryaka Kimsuky July 2025) [Kimsuky](https://attack.mitre.org/groups/G0094) has utilized XOR and RC4 to encode malicious payloads.(Citation: Gen Digital Kimsuky HTTPTroy October 2025) ", "external_references": [{"description": "Alexndru-Cristian Bardas. (2025, October 30). DPRK’s Playbook: Kimsuky’s HttpTroy and Lazarus’s New BLINDINGCAN Variant. Retrieved April 8, 2026.", "source_name": "Gen Digital Kimsuky HTTPTroy October 2025", "url": "https://www.gendigital.com/blog/insights/research/dprk-kimsuky-lazarus-analysis"}, {"description": "Varadharajan Krishnasamy, Aditya K Sood. (2025, July 29). From Reconnaissance to Control: The Operational Blueprint of Kimsuky APT for Cyber Espionage. Retrieved April 18, 2026.", "source_name": "Aryaka Kimsuky July 2025", "url": "https://www.aryaka.com/docs/reports/aryaka-kimsuky-apt-operational-blueprint.pdf"}], "id": "relationship--44f1b846-9e75-4f7b-8b6c-a0e68ccbb3ac", "modified": "2026-07-31T20:48:24.746Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--0d91b3c0-5e50-47c3-949a-2a796f04d144", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7931', 0, 157, '09-mitre-attack', 'retrieved', 'A130191613BEA573C412F286540333260FF537CD736039BFC2A02D199160ADEB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
