VALUES ('doc-09-mitre-attack-p0-7942', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-09T14:13:51.991Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Talos Kimsuky Nov 2021)(Citation: Mandiant APT43 March 2024)", "external_references": [{"description": "An, J and Malhotra, A. (2021, November 10). North Korean attackers use malicious blogs to deliver malware to high-profile South Korean targets. Retrieved December 29, 2021.", "source_name": "Talos Kimsuky Nov 2021", "url": "https://blog.talosintelligence.com/2021/11/kimsuky-abuses-blogs-delivers-malware.html"}, {"description": "Mandiant. (2024, March 14). APT43: North Korean Group Uses Cybercrime to Fund Espionage Operations. Retrieved May 3, 2024.", "source_name": "Mandiant APT43 March 2024", "url": "https://services.google.com/fh/files/misc/apt43-report-en.pdf"}], "id": "relationship--56996982-a954-44d6-9d99-c23d4babccc1", "modified": "2026-07-31T20:48:24.847Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "malware--28b97733-ef07-4414-aaa5-df50b2d30cc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7942', 0, 99, '09-mitre-attack', 'retrieved', '9C385D580E3E8EFFB9927EDB5AB966D7065CF6318E0C56E4D3E4F40361339153', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
