VALUES ('doc-09-mitre-attack-p0-7946', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-15T19:56:31.108Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has searched for information on the target company''s website.(Citation: KISA Operation Muzabi)", "external_references": [{"description": "KISA. (2021). Phishing Target Reconnaissance and Attack Resource Analysis Operation Muzabi. Retrieved March 8, 2024.", "source_name": "KISA Operation Muzabi", "url": "https://web.archive.org/web/20220328121326/https://boho.or.kr/filedownload.do?attach_file_seq=2695&attach_file_id=EpF2695.pdf"}], "id": "relationship--5d705563-a639-4ec1-a19d-f797c1c0c078", "modified": "2026-07-31T20:48:24.881Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--16cdd21f-da65-4e4f-bc04-dd7d198c7b26", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7946', 0, 65, '09-mitre-attack', 'retrieved', '06F36DAA19B642712F9C1357305728659F68B37B961A7EEFA003F86725227B68', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
