VALUES ('doc-09-mitre-attack-p0-7983', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-18T23:45:37.379Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has detected and killed virtual environments by using the PowerShell cmdlet `Get-CimInstance` that searches the classname of the computer system manufacturer through an if statement of `if($computerSystem.Manufacturer -match \"VMware\" -or $computerSystem.Manufacturer -match \"Microsoft\" -or $computerSystem.Manufacturer -match \"VirtualBox\")`.(Citation: Aryaka Kimsuky July 2025)", "external_references": [{"description": "Varadharajan Krishnasamy, Aditya K Sood. (2025, July 29). From Reconnaissance to Control: The Operational Blueprint of Kimsuky APT for Cyber Espionage. Retrieved April 18, 2026.", "source_name": "Aryaka Kimsuky July 2025", "url": "https://www.aryaka.com/docs/reports/aryaka-kimsuky-apt-operational-blueprint.pdf"}], "id": "relationship--9af9b544-da12-4c1d-a5c4-9474b2181365", "modified": "2026-07-31T20:48:25.254Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7983', 0, 105, '09-mitre-attack', 'retrieved', '76CC0593702687EDA8CDBCC4AB5833576D8125204BE8AAC08CE7E81B855D12E3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
