VALUES ('doc-09-mitre-attack-p0-7984', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-07T19:10:03.754Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Mandiant APT43 March 2024)", "external_references": [{"description": "Mandiant. (2024, March 14). APT43: North Korean Group Uses Cybercrime to Fund Espionage Operations. Retrieved May 3, 2024.", "source_name": "Mandiant APT43 March 2024", "url": "https://services.google.com/fh/files/misc/apt43-report-en.pdf"}], "id": "relationship--9f259569-dfd2-4afa-aa0a-8031864c1367", "modified": "2026-07-31T20:48:25.263Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "tool--da04ac30-27da-4959-a67d-450ce47d9470", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7984', 0, 61, '09-mitre-attack', 'retrieved', '2C340F75FAA8C67A66EC1E44F97FAE8AEE65BB19D20DC363E3CF6CEB5AD423A5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
