VALUES ('doc-09-mitre-attack-p0-7987', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-06T18:02:10.616Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used e-mail to send exfiltrated data to C2 servers.(Citation: CISA AA20-301A Kimsuky)", "external_references": [{"description": "CISA, FBI, CNMF. (2020, October 27). https://us-cert.cisa.gov/ncas/alerts/aa20-301a. Retrieved November 4, 2020.", "source_name": "CISA AA20-301A Kimsuky", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-301a"}], "id": "relationship--a573685b-3135-44ae-9f9a-844dfc5bdaa2", "modified": "2026-07-31T20:48:25.287Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--54b4c251-1f0e-4eba-ba6b-dbc7a6f6f06b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7987', 0, 62, '09-mitre-attack', 'retrieved', '79FBAAEAF0223232397EB27EBEA4D3649D998C60607B48C7BC77F58C5AFED945', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
