VALUES ('doc-09-mitre-attack-p0-7991', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-09-29T13:02:30.940Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used tools that are capable of obtaining credentials from saved mail.(Citation: Netscout Stolen Pencil Dec 2018)", "external_references": [{"description": "ASERT team. (2018, December 5). STOLEN PENCIL Campaign Targets Academia. Retrieved February 5, 2019.", "source_name": "Netscout Stolen Pencil Dec 2018", "url": "https://asert.arbornetworks.com/stolen-pencil-campaign-targets-academia/"}], "id": "relationship--a89c60cc-5851-45bf-bcd6-f73f460351a5", "modified": "2026-07-31T20:48:25.320Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--837f9164-50af-4ac0-8219-379d8a74cefc", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7991', 0, 71, '09-mitre-attack', 'retrieved', 'D7DD2D26888B59059B0AE6889115F752413C36433E8CC84CD74DABE8C8935DB8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
