VALUES ('doc-09-mitre-attack-p0-7993', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-09T14:32:47.571Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used QuickZip to archive stolen files before exfiltration.(Citation: Talos Kimsuky Nov 2021) [Kimsuky](https://attack.mitre.org/groups/G0094) has used the Send() function to compress all collected data into a zip file named init,.zip, then renames it to init.dat, before exfiltration.(Citation: Aryaka Kimsuky July 2025)", "external_references": [{"description": "An, J and Malhotra, A. (2021, November 10). North Korean attackers use malicious blogs to deliver malware to high-profile South Korean targets. Retrieved December 29, 2021.", "source_name": "Talos Kimsuky Nov 2021", "url": "https://blog.talosintelligence.com/2021/11/kimsuky-abuses-blogs-delivers-malware.html"}, {"description": "Varadharajan Krishnasamy, Aditya K Sood. (2025, July 29). From Reconnaissance to Control: The Operational Blueprint of Kimsuky APT for Cyber Espionage. Retrieved April 18, 2026.", "source_name": "Aryaka Kimsuky July 2025", "url": "https://www.aryaka.com/docs/reports/aryaka-kimsuky-apt-operational-blueprint.pdf"}], "id": "relationship--b005a049-ecf3-4378-bff6-983b16f92482", "modified": "2026-07-31T20:48:25.334Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--00f90846-cbd1-4fc5-9233-df5c2bf2a662", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7993', 0, 139, '09-mitre-attack', 'retrieved', '0AE73E6B9B9479D6BD7A573B49DD7B60064BA4B0F2CA28EA40B721C4D0E007DE', 'v1', '{"source_id": 