VALUES ('doc-09-mitre-attack-p0-7998', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-26T15:27:12.971Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has a HWP document stealer module which changes the default program association in the registry to open HWP documents.(Citation: Securelist Kimsuky Sept 2013)", "external_references": [{"description": "Tarakanov , D.. (2013, September 11). The “Kimsuky” Operation: A North Korean APT?. Retrieved August 13, 2019.", "source_name": "Securelist Kimsuky Sept 2013", "url": "https://securelist.com/the-kimsuky-operation-a-north-korean-apt/57915/"}], "id": "relationship--b967963e-5dd4-42a3-a94e-8b3d17250aec", "modified": "2026-07-31T20:48:25.372Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--98034fef-d9fb-4667-8dc4-2eab6231724c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-7998', 0, 79, '09-mitre-attack', 'retrieved', 'A308976D0FE7273D823406B850653746F4782CEBC86DB0760680076DCD55C4F1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
