VALUES ('doc-09-mitre-attack-p0-8001', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-08-26T15:27:13.065Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used Win7Elevate to inject malicious code into explorer.exe.(Citation: Securelist Kimsuky Sept 2013)", "external_references": [{"description": "Tarakanov , D.. (2013, September 11). The “Kimsuky” Operation: A North Korean APT?. Retrieved August 13, 2019.", "source_name": "Securelist Kimsuky Sept 2013", "url": "https://securelist.com/the-kimsuky-operation-a-north-korean-apt/57915/"}], "id": "relationship--bd648f03-7313-4e05-bd6e-b499f76a295c", "modified": "2026-07-31T20:48:25.403Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--43e7dc91-05b2-474c-b9ac-2ed4fe101f4d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8001', 0, 69, '09-mitre-attack', 'retrieved', '65F0D71BC642EA4D9A36AB7E9F2AA6BFFA8C0D7F4B7D7EB38E0F92C7476C203D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
