VALUES ('doc-09-mitre-attack-p0-8002', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T22:43:23.367Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has captured browser screenshots using [TRANSLATEXT](https://attack.mitre.org/software/S1201).(Citation: Zscaler Kimsuky TRANSLATEXT) [Kimsuky](https://attack.mitre.org/groups/G0094) has also obtained screen captures with custom malware.(Citation: Gen Digital Kimsuky HTTPTroy October 2025) ", "external_references": [{"description": "Alexndru-Cristian Bardas. (2025, October 30). DPRK’s Playbook: Kimsuky’s HttpTroy and Lazarus’s New BLINDINGCAN Variant. Retrieved April 8, 2026.", "source_name": "Gen Digital Kimsuky HTTPTroy October 2025", "url": "https://www.gendigital.com/blog/insights/research/dprk-kimsuky-lazarus-analysis"}, {"description": "Park, S. (2024, June 27). Kimsuky deploys TRANSLATEXT to target South Korean academia. Retrieved October 14, 2024.", "source_name": "Zscaler Kimsuky TRANSLATEXT", "url": "https://www.zscaler.com/blogs/security-research/kimsuky-deploys-translatext-target-south-korean-academia#technical-analysis"}], "id": "relationship--bf53c414-9ea5-4f56-8f73-eb7d2287f651", "modified": "2026-07-31T20:48:25.412Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8002', 0, 108, '09-mitre-attack', 'retrieved', '863A95C06E310AD1F5DCB7E8273FF435F8DC2E258609A55272E3B4DFE5A94BD2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
