VALUES ('doc-09-mitre-attack-p0-8011', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T23:02:22.878Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used LLMs to identify think tanks, government organizations, and experts to inform targeting for spearphishing campaigns.(Citation: MSFT-AI) ", "external_references": [{"description": "Microsoft Threat Intelligence. (2024, February 14). Staying ahead of threat actors in the age of AI. Retrieved March 11, 2024.", "source_name": "MSFT-AI", "url": "https://www.microsoft.com/en-us/security/blog/2024/02/14/staying-ahead-of-threat-actors-in-the-age-of-ai/"}], "id": "relationship--cd31c0a5-29b0-42c4-9ef6-17ec0bbb0b17", "modified": "2026-07-31T20:48:25.497Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--143122a8-fcda-4dd7-aded-5b9387d9c2d6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8011', 0, 75, '09-mitre-attack', 'retrieved', '0995F11C6663D9CD4FB95826F0F3BB9E0B271D9597FFCA090089915DED4C5A2E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
