VALUES ('doc-09-mitre-attack-p0-8018', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-15T20:02:43.786Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has renamed malware to legitimate names such as ESTCommon.dll or patch.dll .(Citation: Kimsuky Malwarebytes) [Kimsuky](https://attack.mitre.org/groups/G0094) has also disguised payloads using legitimate file names including a PowerShell payload named chrome.ps1. (Citation: Securonix Kimsuky February 2025) [Kimsuky](https://attack.mitre.org/groups/G0094) has also used a malicious QR code that masqueraded as a legitimate package delivery service.(Citation: EnkiWhiteHat_KimsukyDOCSWAP_Dec2025) ", "external_references": [{"description": "Den Iuzvyk, Tim Peck. (2025, February 13). Analyzing DEEP#DRIVE: North Korean Threat Actors Observed Exploiting Trusted Platforms for Targeted Attacks. Retrieved August 19, 2025.", "source_name": "Securonix Kimsuky February 2025", "url": "https://www.securonix.com/blog/analyzing-deepdrive-north-korean-threat-actors-observed-exploiting-trusted-platforms-for-targeted-attacks/"}, {"description": "EnkiWhiteHat. (2025, December 16). Kimsuky Distributing Malicious Mobile App via QR Code. Retrieved January 8, 2026.", "source_name": "EnkiWhiteHat_KimsukyDOCSWAP_Dec2025", "url": "https://www.enki.co.kr/en/media-center/blog/kimsuky-distributing-malicious-mobile-app-via-qr-code"}, {"description": "Hossein Jazi. (2021, June 1). Kimsuky APT continues to target South Korean government using AppleSeed backdoor. Retrieved January 10, 2024.", "source_name": "Kimsuky Malwarebytes", "url": "https://www.malwarebytes.com/blog/threat-intelligence/2021/06/kimsuky-apt-continues-to-target-south-korean-government-using-appleseed-backdoor"}], "id": "relationship--dbbef446-8cc0-43cc-bfae-6fc6d7310e67", "modified": "2026-07-31T20:48:25.550Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8018', 0, 162, '09-mitre-attack', 'retrieved', '1931DC4FA247FA3DB36BCE80CB21B78138F41083C47F0F51AF7F8EEAB23360F4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
