VALUES ('doc-09-mitre-attack-p0-8020', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-08-19T15:51:53.665Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has used an additional filename extension to hide the true file type. [Kimsuky](https://attack.mitre.org/groups/G0094) has also masqueraded malicious LNK files as PDF objects using the double extension .pdf.lnk.(Citation: Securonix Kimsuky February 2025)", "external_references": [{"description": "Den Iuzvyk, Tim Peck. (2025, February 13). Analyzing DEEP#DRIVE: North Korean Threat Actors Observed Exploiting Trusted Platforms for Targeted Attacks. Retrieved August 19, 2025.", "source_name": "Securonix Kimsuky February 2025", "url": "https://www.securonix.com/blog/analyzing-deepdrive-north-korean-threat-actors-observed-exploiting-trusted-platforms-for-targeted-attacks/"}], "id": "relationship--e121b072-4dad-487c-86d3-95ceb100f01a", "modified": "2026-07-31T20:48:25.576Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--11f29a39-0942-4d62-92b6-fe236cf3066e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8020', 0, 94, '09-mitre-attack', 'retrieved', '093B698CB672734E7B9417F6638BA1EA0FA8ADD2D3A093FF6D9FE5B48FDCE6E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
