VALUES ('doc-09-mitre-attack-p0-8022', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-29T22:39:05.482Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kimsuky](https://attack.mitre.org/groups/G0094) has stolen a valid certificate that is used to sign the malware and the dropper.(Citation: S2W Troll Stealer 2024) ", "external_references": [{"description": "Jiho Kim & Sebin Lee, S2W. (2024, February 7). Kimsuky disguised as a Korean company signed with a valid certificate to distribute Troll Stealer (English ver.). Retrieved January 17, 2025.", "source_name": "S2W Troll Stealer 2024", "url": "https://medium.com/s2wblog/kimsuky-disguised-as-a-korean-company-signed-with-a-valid-certificate-to-distribute-troll-stealer-cfa5d54314e2"}], "id": "relationship--e69a5b01-a99c-487c-ac3a-6acc8e36cc55", "modified": "2026-07-31T20:48:25.591Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--0ec2f388-bf0f-4b5c-97b1-fc736d26c25f", "spec_version": "2.1", "target_ref": "attack-pattern--e7cbc1de-1f79-48ee-abfd-da1241c65a15", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8022', 0, 89, '09-mitre-attack', 'retrieved', '9205F1CCF7BF9DC512BD10E3C0EF724C59A3A84A31FC45A292075D80C8CE8384', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
