VALUES ('doc-09-mitre-attack-p0-8070', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.052Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[admin@338](https://attack.mitre.org/groups/G0018) actors used the following command to rename one of their tools to a benign file name: ren \"%temp%\\upload\" audiodg.exe (Citation: FireEye admin@338)", "external_references": [{"description": "FireEye Threat Intelligence. (2015, December 1). China-based Cyber Threat Group Uses Dropbox for Malware Communications and Targets Hong Kong Media Outlets. Retrieved December 4, 2015.", "source_name": "FireEye admin@338", "url": "https://www.fireeye.com/blog/threat-research/2015/11/china-based-threat.html"}], "id": "relationship--4da943df-a7dc-499f-a8b7-ca8d298d8ff6", "modified": "2026-07-31T18:47:39.484Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--16ade1aa-0ea1-4bb7-88cc-9079df2ae756", "spec_version": "2.1", "target_ref": "attack-pattern--1c4e5d32-1fe9-4116-9d9d-59e3925bd6a2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8070', 0, 84, '09-mitre-attack', 'retrieved', '3527BA0E70CA8784EC8168ABAF6813B18FA3E59C47A816556F99273F0607E080', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
