VALUES ('doc-09-mitre-attack-p0-8091', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-04T18:33:26.857Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volt Typhoon](https://attack.mitre.org/groups/G1017) has used compromised Paessler Router Traffic Grapher (PRTG) servers from other organizations for C2.(Citation: Secureworks BRONZE SILHOUETTE May 2023)(Citation: CISA AA24-038A PRC Critical Infrastructure February 2024)", "external_references": [{"description": "CISA et al.. (2024, February 7). PRC State-Sponsored Actors Compromise and Maintain Persistent Access to U.S. Critical Infrastructure. Retrieved May 15, 2024.", "source_name": "CISA AA24-038A PRC Critical Infrastructure February 2024", "url": "https://www.cisa.gov/sites/default/files/2024-03/aa24-038a_csa_prc_state_sponsored_actors_compromise_us_critical_infrastructure_3.pdf"}, {"description": "Counter Threat Unit Research Team. (2023, May 24). Chinese Cyberespionage Group BRONZE SILHOUETTE Targets U.S. Government and Defense Organizations. Retrieved July 27, 2023.", "source_name": "Secureworks BRONZE SILHOUETTE May 2023", "url": "https://web.archive.org/web/20230601025540/https://www.secureworks.com/blog/chinese-cyberespionage-group-bronze-silhouette-targets-us-government-and-defense-organizations"}], "id": "relationship--12948e09-2774-4b91-b9d1-018b41f7f923", "modified": "2026-07-31T18:47:39.663Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--174279b4-399f-4ddb-966e-5efedd1dd5f2", "spec_version": "2.1", "target_ref": "attack-pattern--e196b5c5-8118-4a1c-ab8a-936586ce3db5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8091', 0, 123, '09-mitre-attack', 'retrieved', '01FADD30DB26D4E93E776