VALUES ('doc-09-mitre-attack-p0-8135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-07-31T20:00:27.448Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volt Typhoon](https://attack.mitre.org/groups/G1017) has used the built-in [netsh](https://attack.mitre.org/software/S0108) `port proxy` command to create proxies on compromised systems to facilitate access.(Citation: Microsoft Volt Typhoon May 2023)(Citation: CISA AA24-038A PRC Critical Infrastructure February 2024)", "external_references": [{"description": "CISA et al.. (2024, February 7). PRC State-Sponsored Actors Compromise and Maintain Persistent Access to U.S. Critical Infrastructure. Retrieved May 15, 2024.", "source_name": "CISA AA24-038A PRC Critical Infrastructure February 2024", "url": "https://www.cisa.gov/sites/default/files/2024-03/aa24-038a_csa_prc_state_sponsored_actors_compromise_us_critical_infrastructure_3.pdf"}, {"description": "Microsoft Threat Intelligence. (2023, May 24). Volt Typhoon targets US critical infrastructure with living-off-the-land techniques. Retrieved July 27, 2023.", "source_name": "Microsoft Volt Typhoon May 2023", "url": "https://www.microsoft.com/en-us/security/blog/2023/05/24/volt-typhoon-targets-us-critical-infrastructure-with-living-off-the-land-techniques/"}], "id": "relationship--828d0030-009d-4612-ae30-9dfa3d139e26", "modified": "2026-07-31T18:47:40.698Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--174279b4-399f-4ddb-966e-5efedd1dd5f2", "spec_version": "2.1", "target_ref": "attack-pattern--f6dacc85-b37d-458e-b58d-74fc4bbf5755", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8135', 0, 122, '09-mitre-attack', 'retrieved', 'D699C638F4123EDC95EAB7CD6F6