VALUES ('doc-09-mitre-attack-p0-8162', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-08-02T18:21:42.603Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Volt Typhoon](https://attack.mitre.org/groups/G1017) has stolen files from a sensitive file server and the Active Directory database from targeted environments, and used [Wevtutil](https://attack.mitre.org/software/S0645) to extract event log information.(Citation: Joint Cybersecurity Advisory Volt Typhoon June 2023)(Citation: Secureworks BRONZE SILHOUETTE May 2023)(Citation: CISA AA24-038A PRC Critical Infrastructure February 2024)", "external_references": [{"description": "CISA et al.. (2024, February 7). PRC State-Sponsored Actors Compromise and Maintain Persistent Access to U.S. Critical Infrastructure. Retrieved May 15, 2024.", "source_name": "CISA AA24-038A PRC Critical Infrastructure February 2024", "url": "https://www.cisa.gov/sites/default/files/2024-03/aa24-038a_csa_prc_state_sponsored_actors_compromise_us_critical_infrastructure_3.pdf"}, {"description": "Counter Threat Unit Research Team. (2023, May 24). Chinese Cyberespionage Group BRONZE SILHOUETTE Targets U.S. Government and Defense Organizations. Retrieved July 27, 2023.", "source_name": "Secureworks BRONZE SILHOUETTE May 2023", "url": "https://web.archive.org/web/20230601025540/https://www.secureworks.com/blog/chinese-cyberespionage-group-bronze-silhouette-targets-us-government-and-defense-organizations"}, {"description": "NSA et al. (2023, May 24). People''s Republic of China State-Sponsored Cyber Actor Living off the Land to Evade Detection. Retrieved July 27, 2023.", "source_name": "Joint Cybersecurity Advisory Volt Typhoon June 2023", "url": "https://media.defense.gov/2023/May/24/2003229517/-1/-1/0/CSA_Living_off_the_Land.PDF"}], "id": "relationship--d5f428f5-4c16-495e-bc79-882a92ce75e0", "modified": "2026-07-31T18:47:41.305Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-