VALUES ('doc-09-mitre-attack-p0-8179', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-20T21:13:38.563Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "\n[Volt Typhoon](https://attack.mitre.org/groups/G1017) has accessed a Local State file that contains the AES key used to encrypt passwords stored in the Chrome browser.(Citation: CISA AA24-038A PRC Critical Infrastructure February 2024)", "external_references": [{"description": "CISA et al.. (2024, February 7). PRC State-Sponsored Actors Compromise and Maintain Persistent Access to U.S. Critical Infrastructure. Retrieved May 15, 2024.", "source_name": "CISA AA24-038A PRC Critical Infrastructure February 2024", "url": "https://www.cisa.gov/sites/default/files/2024-03/aa24-038a_csa_prc_state_sponsored_actors_compromise_us_critical_infrastructure_3.pdf"}], "id": "relationship--fa0f9d88-17b4-4ff2-974e-2d12063646b7", "modified": "2026-07-31T18:47:41.647Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--174279b4-399f-4ddb-966e-5efedd1dd5f2", "spec_version": "2.1", "target_ref": "attack-pattern--60b508a1-6a5e-46b1-821a-9f7b78752abf", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8179', 0, 92, '09-mitre-attack', 'retrieved', 'E7E58F8876DD05BCD2F2836CBAD1A36B5C9AEC6DEBEF34913E7841AE41D3C532', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
