VALUES ('doc-09-mitre-attack-p0-8182', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-03-18T18:37:06.748Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Patchwork](https://attack.mitre.org/groups/G0040) used Visual Basic Scripts (VBS) on victim machines.(Citation: TrendMicro Patchwork Dec 2017)(Citation: Volexity Patchwork June 2018)", "external_references": [{"description": "Lunghi, D., et al. (2017, December). Untangling the Patchwork Cyberespionage Group. Retrieved July 10, 2018.", "source_name": "TrendMicro Patchwork Dec 2017", "url": "https://documents.trendmicro.com/assets/tech-brief-untangling-the-patchwork-cyberespionage-group.pdf"}, {"description": "Meltzer, M, et al. (2018, June 07). Patchwork APT Group Targets US Think Tanks. Retrieved July 16, 2018.", "source_name": "Volexity Patchwork June 2018", "url": "https://www.volexity.com/blog/2018/06/07/patchwork-apt-group-targets-us-think-tanks/"}], "id": "relationship--01d1922c-6900-4ed3-8ddf-bae4d06296b3", "modified": "2026-07-31T20:48:26.132Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--17862c7d-9e60-48a0-b48e-da4dc4c3f6b0", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8182', 0, 96, '09-mitre-attack', 'retrieved', '67FE202A8AA06C4FEC7C7CE47CD32FE57069BA704494A881002EFC43CD433B0C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
