VALUES ('doc-09-mitre-attack-p0-8186', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A [Patchwork](https://attack.mitre.org/groups/G0040) .dll that contains [BADNEWS](https://attack.mitre.org/software/S0128) is loaded and executed using DLL side-loading.(Citation: TrendMicro Patchwork Dec 2017)", "external_references": [{"description": "Lunghi, D., et al. (2017, December). Untangling the Patchwork Cyberespionage Group. Retrieved July 10, 2018.", "source_name": "TrendMicro Patchwork Dec 2017", "url": "https://documents.trendmicro.com/assets/tech-brief-untangling-the-patchwork-cyberespionage-group.pdf"}], "id": "relationship--174698f8-9349-4e52-9887-18089038195c", "modified": "2026-07-31T20:48:26.164Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--17862c7d-9e60-48a0-b48e-da4dc4c3f6b0", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8186', 0, 70, '09-mitre-attack', 'retrieved', '052788F1DD1619F573C71E977114F117D7A74737696474692164ECB55AE83A7D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
