VALUES ('doc-09-mitre-attack-p0-8215', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Patchwork](https://attack.mitre.org/groups/G0040) developed a file stealer to search C:\\ and collect files with certain extensions. [Patchwork](https://attack.mitre.org/groups/G0040) also executed a script to enumerate all drives, store them as a list, and upload generated files to the C2 server.(Citation: TrendMicro Patchwork Dec 2017)", "external_references": [{"description": "Lunghi, D., et al. (2017, December). Untangling the Patchwork Cyberespionage Group. Retrieved July 10, 2018.", "source_name": "TrendMicro Patchwork Dec 2017", "url": "https://documents.trendmicro.com/assets/tech-brief-untangling-the-patchwork-cyberespionage-group.pdf"}], "id": "relationship--b0a0e3c7-e1b2-4b84-8e37-8989147785d0", "modified": "2026-07-31T20:48:26.401Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--17862c7d-9e60-48a0-b48e-da4dc4c3f6b0", "spec_version": "2.1", "target_ref": "attack-pattern--30208d3e-0d6b-43c8-883e-44462a514619", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8215', 0, 93, '09-mitre-attack', 'retrieved', '42BD3CEECF219353379FCEE8FB79386A857BDD6FE75219EB7C3867EEA91801B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
