VALUES ('doc-09-mitre-attack-p0-8232', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-22T22:48:25.135Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) uses multiple built-in commands such as systeminfo and `net config Workstation` to enumerate victim system basic configuration information.(Citation: Rostovcev APT41 2021)", "external_references": [{"description": "Nikita Rostovcev. (2022, August 18). APT41 World Tour 2021 on a tight schedule. Retrieved February 22, 2024.", "source_name": "Rostovcev APT41 2021", "url": "https://www.group-ib.com/blog/apt41-world-tour-2021/"}], "id": "relationship--0f9f9bd3-ccea-4369-b8e7-371d1aad5ff8", "modified": "2026-07-31T20:48:26.787Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8232', 0, 76, '09-mitre-attack', 'retrieved', '090DFD072435DFA6B911834F2D77FB191B3E6D3E87507BAA20693A15167D5A77', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
