VALUES ('doc-09-mitre-attack-p0-8266', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-24T00:51:25.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) has encrypted payloads using the Data Protection API (DPAPI), which relies on keys tied to specific user accounts on specific machines. [APT41](https://attack.mitre.org/groups/G0096) has also environmentally keyed second stage malware with an RC5 key derived in part from the infected system''s volume serial number.(Citation: Twitter ItsReallyNick APT41 EK)", "external_references": [{"description": "Carr, N. (2019, October 30). Nick Carr Status Update APT41 Environmental Keying. Retrieved September 12, 2024.", "source_name": "Twitter ItsReallyNick APT41 EK", "url": "https://x.com/ItsReallyNick/status/1189622925286084609"}], "id": "relationship--5212a108-111b-4467-84c9-933d2b84aad2", "modified": "2026-07-31T20:48:27.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--f244b8dd-af6c-4391-a497-fc03627ce995", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8266', 0, 102, '09-mitre-attack', 'retrieved', 'FAB521EA0AE89D841E0B4987154094175457661FBB80F1FB94869E32A990CCCD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
