VALUES ('doc-09-mitre-attack-p0-8290', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-22T22:39:03.833Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) extracted user account data from the Security Account Managerr (SAM), making a copy of this database from the registry using the reg save command or by exploiting volume shadow copies.(Citation: Rostovcev APT41 2021)", "external_references": [{"description": "Nikita Rostovcev. (2022, August 18). APT41 World Tour 2021 on a tight schedule. Retrieved February 22, 2024.", "source_name": "Rostovcev APT41 2021", "url": "https://www.group-ib.com/blog/apt41-world-tour-2021/"}], "id": "relationship--81a6f575-386c-4d8f-ac6c-fa293141eb60", "modified": "2026-07-31T20:48:27.231Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--1644e709-12d2-41e5-a60f-3470991f5011", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8290', 0, 88, '09-mitre-attack', 'retrieved', '027FC4FD71ADEEC8CEEC260E14B3E8A55D474A5E20B8B82A9A83C9E98511821A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
