VALUES ('doc-09-mitre-attack-p0-8308', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-23T23:08:25.404Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) used a ransomware called Encryptor RaaS to encrypt files on the targeted systems and provide a ransom note to the user.(Citation: FireEye APT41 Aug 2019) [APT41](https://attack.mitre.org/groups/G0096) also used Microsoft Bitlocker to encrypt workstations and Jetico’s BestCrypt to encrypt servers.(Citation: apt41_dcsocytec_dec2022)", "external_references": [{"description": "DCSO CyTec Blog. (2022, December 24). APT41 — The spy who failed to encrypt me. Retrieved June 13, 2024.", "source_name": "apt41_dcsocytec_dec2022", "url": "https://medium.com/@DCSO_CyTec/apt41-the-spy-who-failed-to-encrypt-me-24fc0f49cad1"}, {"description": "Fraser, N., et al. (2019, August 7). Double DragonAPT41, a dual espionage and cyber crime operation APT41. Retrieved September 23, 2019.", "source_name": "FireEye APT41 Aug 2019", "url": "https://www.mandiant.com/sites/default/files/2022-02/rt-apt41-dual-operation.pdf"}], "id": "relationship--acfaf7ec-7b92-40ec-a844-17089791a663", "modified": "2026-07-31T20:48:27.442Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8308', 0, 124, '09-mitre-attack', 'retrieved', '2205AF6B619EB5B050395B8E1227E5208ACB9E41B37BEF867080D2C8B5FEDB0F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
