VALUES ('doc-09-mitre-attack-p0-8321', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-09-23T22:53:30.172Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) has used hashdump, [Mimikatz](https://attack.mitre.org/software/S0002), Procdump, and the Windows Credential Editor to dump password hashes from memory and authenticate to other user accounts.(Citation: FireEye APT41 Aug 2019)(Citation: Group IB APT 41 June 2021)(Citation: apt41_dcsocytec_dec2022)", "external_references": [{"description": "DCSO CyTec Blog. (2022, December 24). APT41 — The spy who failed to encrypt me. Retrieved June 13, 2024.", "source_name": "apt41_dcsocytec_dec2022", "url": "https://medium.com/@DCSO_CyTec/apt41-the-spy-who-failed-to-encrypt-me-24fc0f49cad1"}, {"description": "Fraser, N., et al. (2019, August 7). Double DragonAPT41, a dual espionage and cyber crime operation APT41. Retrieved September 23, 2019.", "source_name": "FireEye APT41 Aug 2019", "url": "https://www.mandiant.com/sites/default/files/2022-02/rt-apt41-dual-operation.pdf"}, {"description": "Rostovcev, N. (2021, June 10). Big airline heist APT41 likely behind a third-party attack on Air India. Retrieved August 26, 2021.", "source_name": "Group IB APT 41 June 2021", "url": "https://www.group-ib.com/blog/colunmtk-apt41/"}], "id": "relationship--cbbbc655-e5a7-40e9-be62-7f29727b9f0c", "modified": "2026-07-31T20:48:27.543Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--65f2d882-3f41-4d48-8a06-29af77ec9f90", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8321', 0, 148, '09-mitre-a