VALUES ('doc-09-mitre-attack-p0-8335', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-22T21:58:47.950Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT41](https://attack.mitre.org/groups/G0096) transfers post-exploitation files dividing the payload into fixed-size chunks to evade detection.(Citation: Rostovcev APT41 2021)", "external_references": [{"description": "Nikita Rostovcev. (2022, August 18). APT41 World Tour 2021 on a tight schedule. Retrieved February 22, 2024.", "source_name": "Rostovcev APT41 2021", "url": "https://www.group-ib.com/blog/apt41-world-tour-2021/"}], "id": "relationship--f291084b-a84d-452f-bd1d-d89257c7e8c2", "modified": "2026-07-31T20:48:27.646Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--18854f55-ac7c-4634-bd9a-352dd07613b7", "spec_version": "2.1", "target_ref": "attack-pattern--c3888c54-775d-4b2f-b759-75a2ececcbfd", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8335', 0, 70, '09-mitre-attack', 'retrieved', '50629EBA4AB6002FC93DC194AE384133838370F41EB500659753E9426D68ADA5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
