VALUES ('doc-09-mitre-attack-p0-8353', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T18:46:52.445Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Salt Typhoon](https://attack.mitre.org/groups/G1045) has cracked passwords for accounts with weak encryption obtained from the configuration files of compromised network devices.(Citation: Cisco Salt Typhoon FEB 2025)", "external_references": [{"description": "Cisco Talos. (2025, February 20). Weathering the storm: In the midst of a Typhoon. Retrieved February 24, 2025.", "source_name": "Cisco Salt Typhoon FEB 2025", "url": "https://blog.talosintelligence.com/salt-typhoon-analysis/"}], "id": "relationship--873d3695-4cd9-4e82-93d6-3960ae1efd4a", "modified": "2026-07-31T18:47:41.895Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1c3dcf91-b859-4aae-a09c-ae26dc8b6390", "spec_version": "2.1", "target_ref": "attack-pattern--1d24cdee-9ea2-4189-b08e-af110bf2435d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8353', 0, 81, '09-mitre-attack', 'retrieved', 'D2752A6E0E111152BE25163B8EC1F8731B6D8BAF9A99B7D45B7DC738CC2194E6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
