VALUES ('doc-09-mitre-attack-p0-8354', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T20:31:35.465Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Salt Typhoon](https://attack.mitre.org/groups/G1045) has modified the loopback address on compromised switches and used them as the source of SSH connections to additional devices within the target environment, allowing them to bypass access control lists (ACLs).(Citation: Cisco Salt Typhoon FEB 2025)", "external_references": [{"description": "Cisco Talos. (2025, February 20). Weathering the storm: In the midst of a Typhoon. Retrieved February 24, 2025.", "source_name": "Cisco Salt Typhoon FEB 2025", "url": "https://blog.talosintelligence.com/salt-typhoon-analysis/"}], "id": "relationship--b7367fd5-bdd2-497e-a5f5-415fb833e56b", "modified": "2026-07-31T18:47:41.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1c3dcf91-b859-4aae-a09c-ae26dc8b6390", "spec_version": "2.1", "target_ref": "attack-pattern--2db31dcd-54da-405d-acef-b9129b816ed6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8354', 0, 96, '09-mitre-attack', 'retrieved', 'BA1577C47108B396F7C3ED5F9D76BC8B01742A5AA9BED316FB40FCA96B69777D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
