VALUES ('doc-09-mitre-attack-p0-8388', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-12-06T16:24:29.236Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dragonfly](https://attack.mitre.org/groups/G0035) has disabled host-based firewalls. The group has also globally opened port 3389.(Citation: US-CERT TA18-074A)", "external_references": [{"description": "US-CERT. (2018, March 16). Alert (TA18-074A): Russian Government Cyber Activity Targeting Energy and Other Critical Infrastructure Sectors. Retrieved June 6, 2018.", "source_name": "US-CERT TA18-074A", "url": "https://www.us-cert.gov/ncas/alerts/TA18-074A"}], "id": "relationship--914014ba-ee7d-46da-ab51-609c1f67dec0", "modified": "2026-07-31T20:48:28.526Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1c63d4ec-0a75-4daa-b1df-0d11af3d3cc1", "spec_version": "2.1", "target_ref": "attack-pattern--eec096b8-c207-43df-b6c1-11523861e452", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8388', 0, 72, '09-mitre-attack', 'retrieved', 'C8C48ECA2922CC649EC78692B7CDA3188F7CB7E86836D76E976B624FEAED9F8F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
