VALUES ('doc-09-mitre-attack-p0-8390', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-10-12T21:50:33.176Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dragonfly](https://attack.mitre.org/groups/G0035) has obtained and used tools such as [Mimikatz](https://attack.mitre.org/software/S0002), [CrackMapExec](https://attack.mitre.org/software/S0488), and [PsExec](https://attack.mitre.org/software/S0029).(Citation: Secureworks IRON LIBERTY July 2019)", "external_references": [{"description": "Secureworks. (2019, July 24). Resurgent Iron Liberty Targeting Energy Sector. Retrieved August 12, 2020.", "source_name": "Secureworks IRON LIBERTY July 2019", "url": "https://www.secureworks.com/research/resurgent-iron-liberty-targeting-energy-sector"}], "id": "relationship--9b363538-86e1-446a-a4f8-b3045a7e8f68", "modified": "2026-07-31T20:48:28.540Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1c63d4ec-0a75-4daa-b1df-0d11af3d3cc1", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8390', 0, 70, '09-mitre-attack', 'retrieved', '8CFF1B26A876D7C8DD8AC859D05E3B681F1AB17329EE49A4065DF8D0359CFEC1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
