VALUES ('doc-09-mitre-attack-p0-8391', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-12T17:52:48.629Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Dragonfly](https://attack.mitre.org/groups/G0035) has placed trojanized installers for control system software on legitimate vendor app stores.(Citation: Secureworks IRON LIBERTY July 2019)(Citation: Gigamon Berserk Bear October 2021)", "external_references": [{"description": "Secureworks. (2019, July 24). Resurgent Iron Liberty Targeting Energy Sector. Retrieved August 12, 2020.", "source_name": "Secureworks IRON LIBERTY July 2019", "url": "https://www.secureworks.com/research/resurgent-iron-liberty-targeting-energy-sector"}, {"description": "Slowik, J. (2021, October). THE BAFFLING BERSERK BEAR: A DECADE’S ACTIVITY TARGETING CRITICAL INFRASTRUCTURE. Retrieved December 6, 2021.", "source_name": "Gigamon Berserk Bear October 2021", "url": "https://vblocalhost.com/uploads/VB2021-Slowik.pdf"}], "id": "relationship--9c3ada08-1908-4458-a454-d91fda25ad04", "modified": "2026-07-31T20:48:28.548Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1c63d4ec-0a75-4daa-b1df-0d11af3d3cc1", "spec_version": "2.1", "target_ref": "attack-pattern--bd369cd9-abb8-41ce-b5bb-fff23ee86c00", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8391', 0, 104, '09-mitre-attack', 'retrieved', '42AA9006896D81E2B7C2998E7244DE42231839585F69A84280B1EFFFAB574C38', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
