VALUES ('doc-09-mitre-attack-p0-8433', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-27T21:26:53.151Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Evilnum](https://attack.mitre.org/groups/G0120) has used the malware variant, TerraTV, to load a malicious DLL placed in the TeamViewer directory, instead of the original Windows DLL located in a system folder.(Citation: ESET EvilNum July 2020) ", "external_references": [{"description": "Porolli, M. (2020, July 9). More evil: A deep look at Evilnum and its toolset. Retrieved January 22, 2021.", "source_name": "ESET EvilNum July 2020", "url": "https://www.welivesecurity.com/2020/07/09/more-evil-deep-look-evilnum-toolset/"}], "id": "relationship--67f7ebd0-effb-4169-a184-7d45c614a6ee", "modified": "2026-07-31T18:47:42.451Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--1f0f9a14-11aa-49aa-9174-bcd0eaa979de", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-8433', 0, 90, '09-mitre-attack', 'retrieved', '1FC4A667619904A32539ED021F482C10BFF567A9CD5B732B140CA89DA6351D52', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
